PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE runs (
    run_id TEXT PRIMARY KEY,
    timestamp TEXT NOT NULL,
    paradigm TEXT NOT NULL,
    topology TEXT NOT NULL,
    schema_tier TEXT NOT NULL,
    model TEXT NOT NULL,
    max_retries INTEGER NOT NULL,
    question TEXT NOT NULL,
    final_answer TEXT,
    graph_success INTEGER NOT NULL,
    total_input_tokens INTEGER NOT NULL,
    total_output_tokens INTEGER NOT NULL,
    total_repairs INTEGER NOT NULL,
    total_latency_sec REAL NOT NULL
, dataset TEXT DEFAULT 'hotpotqa');
CREATE TABLE node_runs (
    run_id TEXT NOT NULL,
    node_name TEXT NOT NULL,
    input_tokens INTEGER NOT NULL,
    output_tokens INTEGER NOT NULL,
    num_repairs INTEGER NOT NULL,
    latency_sec REAL NOT NULL,
    success INTEGER NOT NULL,
    final_error TEXT,
    PRIMARY KEY (run_id, node_name),
    FOREIGN KEY (run_id) REFERENCES runs(run_id)
);
CREATE TABLE node_attempts (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    run_id TEXT NOT NULL,
    node_name TEXT NOT NULL,
    attempt_num INTEGER NOT NULL,
    raw_output TEXT,
    input_tokens INTEGER NOT NULL,
    output_tokens INTEGER NOT NULL,
    validation_ok INTEGER NOT NULL,
    primary_category TEXT,
    all_categories TEXT,     -- JSON array
    error_details TEXT, resolved_model_version TEXT,      -- JSON array of full error info
    FOREIGN KEY (run_id) REFERENCES runs(run_id)
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_runs_model ON runs(model);
CREATE INDEX idx_attempts_run ON node_attempts(run_id);
CREATE INDEX idx_attempts_category ON node_attempts(primary_category);
CREATE INDEX idx_attempts_version ON node_attempts(resolved_model_version);
CREATE INDEX idx_runs_dataset ON runs(dataset);
COMMIT;
