INSERT INTO node_attempts VALUES(905,'6d567060-b0dc-487e-b8da-b6985c6313a0','gather',0,replace('{\n  "facts": [\n    {\n      "entity_id": "sci_fantasy_ya_series",\n      "fact": "The ''Lorien Legacies'' series by Pittacus Lore is a science fantasy young adult series told in first person, following alien survivors on Earth. However, ''The Remnant Chronicles'' and other series also fit partially. The best match is likely ''Lorien Legacies'' which has companion books called ''The Lost Files'' detailing other characters and worlds.",\n      "relevance": 0.9\n    },\n    {\n      "entity_id": "companion_books",\n      "fact": "The Lorien Legacies series has a set of companion novellas called ''The Lost Files'' (and later ''The Fugitive'') that narrate the stories of other Garde members, Cêpan, and alien species beyond the main narrative.",\n      "relevance": 0.95\n    },\n    {\n      "entity_id": "enslaved_worlds",\n      "fact": "In the Lorien Legacies universe, the planet Lorien was conquered and its people enslaved/destroyed by the Mogadorians, and companion books explore the stories of these conquered peoples and other worlds affected by Mogadorian expansion.",\n      "relevance": 0.85\n    },\n    {\n      "entity_id": "first_person_narrative",\n      "fact": "The main Lorien Legacies novels (starting with ''I Am Number Four'') are told in first person from the perspective of Number Four (John Smith), an alien refugee hiding on Earth.",\n      "relevance": 0.9\n    },\n    {\n      "entity_id": "alien_species",\n      "fact": "The Lorien Legacies series features multiple alien species including the Loric (protagonists) and the Mogadorians (antagonists), with companion books expanding on the biology, culture, and histories of these species.",\n      "relevance": 0.85\n    }\n  ],\n  "fact_count": 5,\n  "coverage_notes": "All five entities are covered. The series most consistent with all criteria—science fantasy YA, first-person narration, companion books about enslaved worlds and alien species—is the Lorien Legacies by Pittacus Lore, with its ''Lost Files'' companion novellas."\n}','\n',char(10)),691,563,0,'length_bound','["length_bound"]','[{"category": "length_bound", "loc": "coverage_notes", "type": "string_too_long", "msg": "String should have at most 250 characters"}]','claude-sonnet-4-6');
