INSERT INTO node_attempts VALUES(1001,'111aee00-5ceb-47af-b6c1-195d85c1cba5','gather',0,replace('{\n  "facts": [\n    {\n      "entity_id": "tunnels_and_trolls",\n      "fact": "Tunnels and Trolls is a fantasy role-playing game first published in 1975, designed by Ken St. Andre, and is one of the earliest RPGs after Dungeons & Dragons.",\n      "relevance": 0.8\n    },\n    {\n      "entity_id": "tunnels_and_trolls",\n      "fact": "In Tunnels and Trolls, the term used for an adventure module or scenario is called a ''solo'' (for single-player adventures) or ''dungeon'', but the general in-game term for an adventure is called a ''delve''.",\n      "relevance": 0.95\n    },\n    {\n      "entity_id": "ken_st_andre",\n      "fact": "Ken St. Andre designed Tunnels and Trolls in 1975 and coined specific terminology for the game, including the name used for adventures within the system.",\n      "relevance": 0.85\n    },\n    {\n      "entity_id": "adventure_concept",\n      "fact": "In Tunnels and Trolls, adventures are referred to as ''delves'', distinguishing the game''s terminology from other RPGs that use terms like ''modules'' or ''quests''.",\n      "relevance": 1.0\n    }\n  ],\n  "fact_count": 4,\n  "coverage_notes": "Facts cover the game''s origin, designer, and the specific terminology used for adventures in Tunnels and Trolls. The key answer is that adventures in T&T are called ''delves''."\n}','\n',char(10)),653,401,1,NULL,NULL,NULL,'claude-sonnet-4-6');
INSERT INTO node_attempts VALUES(1002,'111aee00-5ceb-47af-b6c1-195d85c1cba5','answer',0,'{"answer":"In Tunnels and Trolls, designed by Ken St. Andre, the term used for an adventure is called a ''delve''. This terminology distinguishes the game from other RPGs that use terms like ''modules'' or ''quests''.", "supporting_entity_ids": ["tunnels_and_trolls", "ken_st_andre", "adventure_concept"], "confidence": 0.85, "confidence_bucket": "high"}',686,105,1,NULL,NULL,NULL,'claude-sonnet-4-6');
