INSERT INTO node_attempts VALUES(1011,'83eff654-54b4-4743-8936-37b39b91646a','gather',0,replace('{\n  "facts": [\n    {\n      "entity_id": "loiseau_blanc",\n      "fact": "L''Oiseau Blanc (The White Bird) was a Levasseur PL.8 biplane that attempted a transatlantic flight from Paris to New York in May 1927.",\n      "relevance": 0.95\n    },\n    {\n      "entity_id": "loiseau_blanc",\n      "fact": "L''Oiseau Blanc was piloted by Charles Nungesser and François Coli, who departed Le Bourget airport on May 8, 1927, and disappeared over the Atlantic Ocean, never reaching their destination.",\n      "relevance": 1.0\n    },\n    {\n      "entity_id": "french_ace_pilot",\n      "fact": "Charles Nungesser was a celebrated French World War I flying ace with 45 aerial victories, known for his daring and adventurous spirit, who co-piloted L''Oiseau Blanc with navigator François Coli.",\n      "relevance": 1.0\n    },\n    {\n      "entity_id": "french_ace_pilot",\n      "fact": "François Coli was a French aviator and navigator, also a WWI veteran, who partnered with Nungesser on the ill-fated transatlantic attempt aboard L''Oiseau Blanc.",\n      "relevance": 0.85\n    }\n  ],\n  "fact_count": 4,\n  "coverage_notes": "Both entities are well covered: L''Oiseau Blanc is identified as the aircraft and its fate, while the French ace pilot entity is clarified as Charles Nungesser (the ace) alongside co-pilot François Coli."\n}','\n',char(10)),626,421,1,NULL,NULL,NULL,'claude-sonnet-4-6');
INSERT INTO node_attempts VALUES(1012,'83eff654-54b4-4743-8936-37b39b91646a','answer',0,'{"answer":"L''Oiseau Blanc was flown by Charles Nungesser, a celebrated French World War I flying ace with 45 aerial victories, and François Coli, his navigator and fellow WWI veteran. They departed Le Bourget airport on May 8, 1927, attempting a transatlantic flight from Paris to New York, but disappeared over the Atlantic Ocean and never reached their destination.","supporting_entity_ids":["loiseau_blanc","french_ace_pilot"],"confidence":0.99,"confidence_bucket":"high"}',691,126,1,NULL,NULL,NULL,'claude-sonnet-4-6');
