INSERT INTO node_attempts VALUES(1020,'a7ac0815-edeb-409d-b19b-827860730054','gather',0,replace('{\n  "facts": [\n    {\n      "entity_id": "alexander_kerensky",\n      "fact": "Alexander Kerensky was the leader of the Russian Provisional Government who was overthrown by the Bolsheviks during the October Revolution of 1917 and fled into exile.",\n      "relevance": 0.85\n    },\n    {\n      "entity_id": "bolsheviks",\n      "fact": "The Bolsheviks, led by Vladimir Lenin, seized power in October 1917 and subsequently fought the Russian Civil War against the White Army and other anti-Bolshevik forces.",\n      "relevance": 0.8\n    },\n    {\n      "entity_id": "russian_civil_war",\n      "fact": "The Russian Civil War lasted from 1917 to 1922, ending with the Bolshevik (Red Army) victory and the establishment of the Soviet Union in December 1922.",\n      "relevance": 1.0\n    },\n    {\n      "entity_id": "russian_civil_war",\n      "fact": "The last major White Army resistance collapsed in 1920-1922, with the Far Eastern Republic being absorbed into Soviet Russia in November 1922, marking the effective end of the civil war.",\n      "relevance": 0.9\n    }\n  ],\n  "fact_count": 4,\n  "coverage_notes": "The question contains a factual inaccuracy: Kerensky was not ''destroyed'' in the civil war but was overthrown in 1917 and lived in exile until 1970. The civil war ended in 1922 with Bolshevik victory."\n}','\n',char(10)),653,397,1,NULL,NULL,NULL,'claude-sonnet-4-6');
INSERT INTO node_attempts VALUES(1021,'a7ac0815-edeb-409d-b19b-827860730054','answer',0,'{"answer":"The Russian Civil War, in which the Bolsheviks defeated their opponents (including forces associated with the former Provisional Government led by Alexander Kerensky), ended in 1922. The last major White Army resistance collapsed between 1920 and 1922, with the Far Eastern Republic being absorbed into Soviet Russia in November 1922, marking the effective end of the conflict and leading to the establishment of the Soviet Union in December 1922.","supporting_entity_ids":["russian_civil_war","bolsheviks","alexander_kerensky"],"confidence":0.95,"confidence_bucket":"high"}',669,139,0,'length_bound','["length_bound"]','[{"category": "length_bound", "loc": "answer", "type": "string_too_long", "msg": "String should have at most 400 characters"}]','claude-sonnet-4-6');
INSERT INTO node_attempts VALUES(1022,'a7ac0815-edeb-409d-b19b-827860730054','answer',1,'{"answer":"The Russian Civil War ended in 1922. The last major White Army resistance collapsed in 1920–1922, with the Far Eastern Republic absorbed into Soviet Russia in November 1922, marking the war''s effective end and leading to the establishment of the Soviet Union in December 1922.","supporting_entity_ids":["russian_civil_war","bolsheviks","alexander_kerensky"],"confidence":0.95,"confidence_bucket":"high"}',919,105,1,NULL,NULL,NULL,'claude-sonnet-4-6');
