INSERT INTO node_attempts VALUES(1047,'6675e4d1-916b-4c91-981e-74f8984d4dd7','gather',0,replace('{\n  "facts": [\n    {\n      "entity_id": "giuseppe_arimondi",\n      "fact": "Giuseppe Arimondi was an Italian general who was killed at the Battle of Adwa (Adowa) on March 1, 1896, during the First Italo-Ethiopian War.",\n      "relevance": 1.0\n    },\n    {\n      "entity_id": "battle",\n      "fact": "The Battle of Adwa (1896) was a decisive Ethiopian victory over Italian forces, in which Italian generals including Arimondi, Dabormida, and Vittorio Dabormida were killed.",\n      "relevance": 1.0\n    },\n    {\n      "entity_id": "ethiopia",\n      "fact": "Ethiopia''s victory at the Battle of Adwa secured its independence and sovereignty, forcing Italy to recognize Ethiopia as a fully independent state in the subsequent Treaty of Addis Ababa (October 1896).",\n      "relevance": 1.0\n    },\n    {\n      "entity_id": "ethiopia",\n      "fact": "The Battle of Adwa made Ethiopia the only African nation to successfully defeat a European colonial power during the Scramble for Africa, preserving its status as an independent nation.",\n      "relevance": 0.9\n    }\n  ],\n  "fact_count": 4,\n  "coverage_notes": "All three entities are covered. The key facts establish that Arimondi died at the Battle of Adwa, and that this battle secured Ethiopian independence and sovereignty, recognized by Italy in the Treaty of Addis Ababa."\n}','\n',char(10)),631,381,1,NULL,NULL,NULL,'claude-sonnet-4-6');
