INSERT INTO node_attempts VALUES(1079,'a1c23e31-5434-4066-a108-bd9699728493','gather',0,replace('{\n  "facts": [\n    {\n      "entity_id": "kiss_and_tell",\n      "fact": "Kiss and Tell is a 1945 film adaptation of the play of the same name, in which Shirley Temple portrayed the character Corliss Archer.",\n      "relevance": 1.0\n    },\n    {\n      "entity_id": "corliss_archer",\n      "fact": "Corliss Archer is a fictional teenage character from the play ''Kiss and Tell'' (1943) by F. Hugh Herbert, portrayed by Shirley Temple in the 1945 film version.",\n      "relevance": 0.9\n    },\n    {\n      "entity_id": "government_position",\n      "fact": "Shirley Temple, who portrayed Corliss Archer in the 1945 film Kiss and Tell, later served as the United States Ambassador to Ghana (1974–1976) and as the U.S. Ambassador to Czechoslovakia (1989–1992), as well as Chief of Protocol of the United States (1976–1977).",\n      "relevance": 1.0\n    }\n  ],\n  "fact_count": 3,\n  "coverage_notes": "The key facts establish that Shirley Temple played Corliss Archer in the 1945 film Kiss and Tell, and that she later held several government positions including U.S. Ambassador to Ghana, Chief of Protocol of the United States, and U.S. Ambassador to Czechoslovakia. The most commonly cited answer to this question is Ambassador to Ghana or Chief of Protocol."\n}','\n',char(10)),630,376,1,NULL,NULL,NULL,'claude-sonnet-4-6');
