INSERT INTO node_attempts VALUES(1146,'6d801527-0c18-4cf6-a470-1a9fb0360e74','gather',0,replace('{\n  "facts": [\n    {\n      "entity_id": "apple_remote",\n      "fact": "The Apple Remote was originally designed to control Front Row, Apple''s media center application.",\n      "relevance": 0.9\n    },\n    {\n      "entity_id": "front_row",\n      "fact": "Front Row is a media center application originally designed to be controlled by the Apple Remote, but it can also be controlled using a keyboard (specifically the keyboard shortcut Command+Escape to launch it, and arrow keys/Enter to navigate).",\n      "relevance": 1.0\n    },\n    {\n      "entity_id": "front_row",\n      "fact": "Front Row can be controlled by a MacBook''s built-in keyboard as an alternative to the Apple Remote, allowing users to navigate media without the physical remote.",\n      "relevance": 0.95\n    }\n  ],\n  "fact_count": 3,\n  "coverage_notes": "The Apple Remote was designed for Front Row. Front Row can also be controlled via the keyboard, making the keyboard the other device/input method that can control Front Row aside from the Apple Remote."\n}','\n',char(10)),604,272,1,NULL,NULL,NULL,'claude-sonnet-4-6');
