INSERT INTO node_attempts VALUES(1170,'42f09bfe-a20f-4979-a71e-7176f86b66bf','gather',0,replace('{\n  "facts": [\n    {\n      "entity_id": "tunnels_and_trolls",\n      "fact": "In Tunnels and Trolls, the adventure (equivalent to a ''dungeon'' or ''module'' in other RPGs) is called a ''delve''.",\n      "relevance": 0.95\n    },\n    {\n      "entity_id": "tunnels_and_trolls",\n      "fact": "Tunnels and Trolls is a fantasy role-playing game first published in 1975, and it uses its own unique terminology distinct from Dungeons & Dragons, including calling its adventures ''solo'' or ''dungeon'' adventures, though the specific term for an adventure module is ''delve''.",\n      "relevance": 0.8\n    },\n    {\n      "entity_id": "ken_st_andre",\n      "fact": "Ken St. Andre designed Tunnels and Trolls in 1975, making it one of the earliest fantasy role-playing games, and he intentionally used different terminology from D&D throughout the game system.",\n      "relevance": 0.7\n    }\n  ],\n  "fact_count": 3,\n  "coverage_notes": "The key answer is that in Tunnels and Trolls, an adventure is called a ''delve''. Ken St. Andre designed the game with intentionally different terminology from D&D. The facts cover both the specific terminology and the designer''s intent."\n}','\n',char(10)),620,350,1,NULL,NULL,NULL,'claude-sonnet-4-6');
INSERT INTO node_attempts VALUES(1171,'42f09bfe-a20f-4979-a71e-7176f86b66bf','answer',0,'{"answer": "In Tunnels and Trolls, the adventure (equivalent to a ''dungeon'' or ''module'' in other RPGs like Dungeons & Dragons) is called a ''delve''. This unique terminology was intentionally chosen by designer Ken St. Andre to distinguish his game from D&D when he created it in 1975.", "supporting_entity_ids": ["tunnels_and_trolls", "ken_st_andre"], "confidence": 0.85, "confidence_bucket": "high"}',630,120,1,NULL,NULL,NULL,'claude-sonnet-4-6');
