INSERT INTO node_attempts VALUES(1195,'a09b383f-29a8-472a-b0a5-0e1b6868ba29','answer',0,'{"answer":"The Livesey Hall War Memorial commemorates the fallen of World War II (the Second World War, 1939–1945), which had an estimated 70–85 million casualties, well exceeding 60 million, making it the deadliest conflict in human history.", "supporting_entity_ids": ["livesey_hall_war_memorial", "world_war_ii"], "confidence": 0.97, "confidence_bucket": "high"}',609,107,1,NULL,NULL,NULL,'claude-sonnet-4-6');
