INSERT INTO node_attempts VALUES(1215,'90e0e131-1122-4047-9a00-2e87e71affd1','gather',0,replace('{\n  "facts": [\n    {\n      "entity_id": "giuseppe_arimondi",\n      "fact": "Giuseppe Arimondi was an Italian general who was killed at the Battle of Adwa (Adowa) on March 1, 1896, during the First Italo-Ethiopian War.",\n      "relevance": 1.0\n    },\n    {\n      "entity_id": "battle_arimondi",\n      "fact": "The Battle of Adwa (1896) was a decisive Ethiopian victory over Italian forces, in which Italian generals Vittorio Dabormida and Giuseppe Arimondi were killed.",\n      "relevance": 1.0\n    },\n    {\n      "entity_id": "ethiopia",\n      "fact": "Ethiopia''s victory at the Battle of Adwa secured its independence and sovereignty, making it one of the few African nations to successfully resist European colonial conquest. Italy was forced to recognize Ethiopian independence in the subsequent Treaty of Addis Ababa.",\n      "relevance": 1.0\n    }\n  ],\n  "fact_count": 3,\n  "coverage_notes": "All three entities are well covered. The Battle of Adwa is clearly identified as the battle where Arimondi died, and the outcome for Ethiopia (secured independence/sovereignty) is established through the Treaty of Addis Ababa following the Italian defeat."\n}','\n',char(10)),618,323,1,NULL,NULL,NULL,'claude-sonnet-4-6');
INSERT INTO node_attempts VALUES(1216,'90e0e131-1122-4047-9a00-2e87e71affd1','answer',0,'{"answer":"The Battle of Adwa (1896), in which Giuseppe Arimondi lost his life, secured Ethiopia''s independence and sovereignty. It was a decisive Ethiopian victory over Italian forces, making Ethiopia one of the few African nations to successfully resist European colonial conquest. Italy was subsequently forced to recognize Ethiopian independence in the Treaty of Addis Ababa.","supporting_entity_ids":["giuseppe_arimondi","battle_arimondi","ethiopia"],"confidence":0.99,"confidence_bucket":"high"}',596,113,1,NULL,NULL,NULL,'claude-sonnet-4-6');
