INSERT INTO node_attempts VALUES(1329,'1e149c46-56db-4fff-84fc-bebf5af6475a','gather',0,replace('{\n  "facts": [\n    {\n      "entity_id": "kaiser_ventures",\n      "fact": "Kaiser Ventures Inc. was a corporation that emerged from Kaiser Steel, founded by Henry J. Kaiser, and was involved in the redevelopment and environmental cleanup of the former Kaiser Steel mill site in Fontana, California.",\n      "relevance": 0.9\n    },\n    {\n      "entity_id": "kaiser_ventures",\n      "fact": "Kaiser Ventures traces its origins to Henry J. Kaiser''s industrial empire, which included Kaiser Steel Corporation, Kaiser Aluminum, and Kaiser Permanente, among many other enterprises built during the 20th century.",\n      "relevance": 0.85\n    },\n    {\n      "entity_id": "father_modern_shipbuilding",\n      "fact": "Henry J. Kaiser is widely known as the ''father of modern American shipbuilding'' due to his revolutionary mass-production techniques used to build Liberty Ships during World War II, dramatically reducing construction time from over a year to just days.",\n      "relevance": 1.0\n    },\n    {\n      "entity_id": "father_modern_shipbuilding",\n      "fact": "Henry J. Kaiser founded Kaiser Ventures (through his broader Kaiser industrial conglomerate) and was the American industrialist credited with transforming U.S. shipbuilding capacity during WWII, producing over 1,490 ships through his Kaiser Shipyards.",\n      "relevance": 0.95\n    }\n  ],\n  "fact_count": 4,\n  "coverage_notes": "Both entities are well covered. Kaiser Ventures is linked to Henry J. Kaiser''s industrial legacy, and the concept of ''Father of Modern American Shipbuilding'' is clearly identified as Henry J. Kaiser, directly connecting the two entities and answering the question affirmatively."\n}','\n',char(10)),616,430,1,NULL,NULL,NULL,'claude-sonnet-4-6');
INSERT INTO node_attempts VALUES(1330,'1e149c46-56db-4fff-84fc-bebf5af6475a','answer',0,'{"answer":"Yes, Kaiser Ventures corporation was founded by Henry J. Kaiser, an American industrialist who is widely known as the ''father of modern American shipbuilding.'' Kaiser revolutionized U.S. shipbuilding during World War II through mass-production techniques at his Kaiser Shipyards, dramatically reducing Liberty Ship construction time from over a year to just days, and producing over 1,490 ships. Kaiser Ventures itself emerged from his broader industrial empire, which also included Kaiser Steel Corporation, Kaiser Aluminum, and Kaiser Permanente, among many other enterprises.", "supporting_entity_ids": ["kaiser_ventures", "father_modern_shipbuilding"], "confidence": 0.99, "confidence_bucket": "high"}',682,162,1,NULL,NULL,NULL,'claude-sonnet-4-6');
INSERT INTO node_attempts VALUES(1331,'51d5add4-49c8-47c4-9dac-c65e9e34b03c','identify',0,replace('{\n  "entities": [\n    {\n      "name": "Tunnels and Trolls",\n      "entity_type": "other",\n      "canonical_id": "tunnels_and_trolls"\n    },\n    {\n      "name": "Ken St. Andre",\n      "entity_type": "person",\n      "canonical_id": "ken_st_andre"\n    },\n    {\n      "name": "Adventure",\n      "entity_type": "concept",\n      "canonical_id": "adventure_concept"\n    }\n  ],\n  "question_type": "what",\n  "primary_entity_id": "tunnels_and_trolls",\n  "entity_count": 3\n}','\n',char(10)),680,175,1,NULL,NULL,NULL,'claude-sonnet-4-6');
INSERT INTO node_attempts VALUES(1332,'51d5add4-49c8-47c4-9dac-c65e9e34b03c','gather',0,'{"facts":[{"entity_id":"tunnels_and_trolls","fact":"Tunnels and Trolls is a fantasy role-playing game first published in 1975, designed by Ken St. Andre. In Tunnels and Trolls, the equivalent of what other RPGs call an ''adventure'' or ''module'' is called a ''solo'' or ''dungeon'', but the specific term used for a published adventure scenario is called a ''solo adventure'' — however, the game uses the term ''dungeon'' for group adventures and ''solo'' for single-player adventures.","relevance":0.9},{"entity_id":"ken_st_andre","fact":"Ken St. Andre designed Tunnels and Trolls in 1975, making it one of the earliest fantasy RPGs. He coined specific terminology for the game, including using the word ''delve'' and notably calling adventure scenarios by a unique name distinct from other RPGs.","relevance":0.85},{"entity_id":"adventure_concept","fact":"In Tunnels and Trolls, the published adventure scenarios (equivalent to ''modules'' in Dungeons & Dragons) are called ''solos'' when designed for one player, and the general term used for an adventure in Tunnels and Trolls is a ''dungeon'' — but the overarching published adventure format is commonly referred to as a ''solo'' in T&T terminology.","relevance":0.9}],"fact_count":3,"coverage_notes":"The key answer the question is looking for is that in Tunnels and Trolls, the term for an adventure (what D&D calls a ''module'') is called a ''solo'' (for single-player) or more generally the adventures are referred to by the game-specific term. The most notable unique terminology is ''solo'' for single-player adventures. Some sources also note the term ''dungeon'' is used for the adventure location/scenario itself."}',636,443,1,NULL,NULL,NULL,'claude-sonnet-4-6');
INSERT INTO node_attempts VALUES(1333,'51d5add4-49c8-47c4-9dac-c65e9e34b03c','answer',0,'{"answer": "In Tunnels and Trolls, the equivalent of what other RPGs (like Dungeons & Dragons) call an ''adventure'' or ''module'' is referred to by specific terms depending on the format: ''solo'' (or ''solo adventure'') for single-player scenarios, and ''dungeon'' for group adventures. The published adventure scenarios in T&T are most distinctively called ''solos,'' which is the term most uniquely associated with the game''s terminology as coined by designer Ken St. Andre.", "supporting_entity_ids": ["tunnels_and_trolls", "ken_st_andre", "adventure_concept"], "confidence": 0.72, "confidence_bucket": "medium"}',737,164,1,NULL,NULL,NULL,'claude-sonnet-4-6');
