INSERT INTO node_attempts VALUES(1341,'39699208-017b-4bb2-ad9f-96b0401badbd','gather',0,replace('{\n  "facts": [\n    {\n      "entity_id": "loiseau_blanc",\n      "fact": "L''Oiseau Blanc (The White Bird) was a Levasseur PL-8 biplane that attempted a transatlantic flight from Paris to New York in May 1927, disappearing over the Atlantic Ocean.",\n      "relevance": 1.0\n    },\n    {\n      "entity_id": "loiseau_blanc",\n      "fact": "L''Oiseau Blanc was piloted by Charles Nungesser and François Coli, who departed from Le Bourget airfield, Paris, on May 8, 1927, and were never seen again.",\n      "relevance": 1.0\n    },\n    {\n      "entity_id": "french_ace_pilot",\n      "fact": "Charles Nungesser was a celebrated French World War I flying ace with 45 aerial victories, known for his daring and adventurous spirit, who co-piloted L''Oiseau Blanc with navigator François Coli.",\n      "relevance": 1.0\n    },\n    {\n      "entity_id": "french_ace_pilot",\n      "fact": "François Coli was a French aviator and navigator, also a WWI veteran, who partnered with Nungesser on the ill-fated transatlantic attempt aboard L''Oiseau Blanc, two weeks before Lindbergh''s successful crossing.",\n      "relevance": 0.9\n    }\n  ],\n  "fact_count": 4,\n  "coverage_notes": "Both entities are well covered. L''Oiseau Blanc is identified as the aircraft used in the 1927 transatlantic attempt, and the French ace pilots are identified as Charles Nungesser (the primary ace with 45 victories) and François Coli. The question likely refers primarily to Nungesser as the ''ace pilot and adventurer,'' with Coli as the navigator/co-pilot."\n}','\n',char(10)),609,479,1,NULL,NULL,NULL,'claude-sonnet-4-6');
INSERT INTO node_attempts VALUES(1342,'39699208-017b-4bb2-ad9f-96b0401badbd','answer',0,'{"answer": "L''Oiseau Blanc was flown by Charles Nungesser and François Coli. Charles Nungesser was the celebrated French World War I flying ace with 45 aerial victories, renowned for his daring and adventurous spirit. François Coli was his navigator and fellow WWI veteran. Together, they departed from Le Bourget airfield in Paris on May 8, 1927, attempting a transatlantic flight to New York, but tragically disappeared over the Atlantic Ocean — just two weeks before Charles Lindbergh completed his successful crossing.", "supporting_entity_ids": ["loiseau_blanc", "french_ace_pilot"], "confidence": 0.99, "confidence_bucket": "high"}',690,167,1,NULL,NULL,NULL,'claude-sonnet-4-6');
