INSERT INTO node_attempts VALUES(1347,'8310ae48-4aa2-4fa9-9a23-22ff9e2d6f6d','gather',0,replace('{\n  "facts": [\n    {\n      "entity_id": "letters_to_cleo",\n      "fact": "Letters to Cleo was a rock band from Boston, Massachusetts, consisting of 5 members: Kay Hanley (vocals), Greg McKenna (guitar), Michael Eisenstein (guitar), Scott Riebling (bass), and Tom Polce (drums).",\n      "relevance": 1.0\n    },\n    {\n      "entity_id": "screaming_trees",\n      "fact": "Screaming Trees was a rock band from Ellensburg, Washington, consisting of 4 members: Mark Lanegan (vocals), Gary Lee Conner (guitar), Van Conner (bass), and Barrett Martin (drums, later replacing Mark Pickerel).",\n      "relevance": 1.0\n    }\n  ],\n  "fact_count": 2,\n  "coverage_notes": "Letters to Cleo had 5 members while Screaming Trees had 4 members, making Letters to Cleo the band with more members. Both bands'' lineups are well-documented, though Screaming Trees had some lineup changes over the years (notably the drummer position)."\n}','\n',char(10)),608,285,1,NULL,NULL,NULL,'claude-sonnet-4-6');
