INSERT INTO node_attempts VALUES(1390,'2a6613f8-ce27-40ed-b7f0-6f32eec1f2b2','gather',0,replace('{\n  "facts": [\n    {\n      "entity_id": "soviet_statesman",\n      "fact": "Mikhail Gorbachev, the former Soviet statesman and last leader of the Soviet Union, initiated the Valdai Discussion Club, but more notably he founded the Gorbachev Foundation. However, the most relevant answer is that Gorbachev initiated a ''parliamentary forum'' concept, though the key figure often cited is Nikita Khrushchev or others. Most precisely, Mikhail Gorbachev is credited with initiating the World Political Forum, an international think tank.",\n      "relevance": 0.7\n    },\n    {\n      "entity_id": "soviet_statesman",\n      "fact": "Mikhail Gorbachev founded the World Political Forum in 2003, an international organization aimed at promoting dialogue on global political issues. He is the most prominent former Soviet statesman associated with initiating an international forum.",\n      "relevance": 0.95\n    },\n    {\n      "entity_id": "forum",\n      "fact": "The World Political Forum, initiated by Mikhail Gorbachev, is described as an international think tank and discussion platform focused on global governance, democracy, and political challenges facing the modern world.",\n      "relevance": 0.9\n    },\n    {\n      "entity_id": "soviet_union",\n      "fact": "The Soviet Union was a socialist state that existed from 1922 to 1991, and its former leaders and statesmen have been involved in various international initiatives after its dissolution.",\n      "relevance": 0.4\n    }\n  ],\n  "fact_count": 4,\n  "coverage_notes": "The question asks about a former Soviet statesman who initiated a forum. Mikhail Gorbachev, the last leader of the Soviet Union, is the most prominent match — he founded the World Political Forum in 2003. Facts cover the statesman''s identity, the specific forum he initiated, and background on the Soviet Union context."\n}','\n',char(10)),610,475,1,NULL,NULL,NULL,'claude-sonnet-4-6');
INSERT INTO node_attempts VALUES(1391,'2a6613f8-ce27-40ed-b7f0-6f32eec1f2b2','answer',0,'{"answer":"The former Soviet statesman Mikhail Gorbachev initiated the World Political Forum, an international think tank and discussion platform focused on global governance, democracy, and political challenges facing the modern world. He founded it in 2003 after the dissolution of the Soviet Union.","supporting_entity_ids":["soviet_statesman","forum"],"confidence":0.85,"confidence_bucket":"high"}',704,91,1,NULL,NULL,NULL,'claude-sonnet-4-6');
