INSERT INTO node_attempts VALUES(1621,'b463bf7d-686e-46ed-947d-aed62338affb','gather',0,'{"facts":[{"entity_id":"alexander_kerensky","fact":"Alexander Kerensky led the Russian Provisional Government during 1917 and was overthrown by the Bolsheviks in the October Revolution.","relevance":0.88},{"entity_id":"alexander_kerensky","fact":"Kerensky left Russia after the Bolshevik seizure of power and did not lead the principal anti-Bolshevik forces during the later Civil War.","relevance":0.82},{"entity_id":"bolsheviks","fact":"The Bolsheviks, led by Lenin, defeated the major White and other anti-Bolshevik forces during the Russian Civil War.","relevance":0.96},{"entity_id":"bolsheviks","fact":"Bolshevik victory was substantially secured by 1920, although fighting and anti-Soviet resistance continued in some regions afterward.","relevance":0.93},{"entity_id":"russian_civil_war","fact":"The Russian Civil War is commonly dated from 1917 to 1922, ending with the Bolsheviks'' victory and the defeat of the main opposing forces.","relevance":1.0},{"entity_id":"russian_civil_war","fact":"Some accounts extend the end of the Russian Civil War to 1923 because isolated anti-Bolshevik resistance continued after the main war had ended.","relevance":0.91}],"fact_count":6,"coverage_notes":"These facts distinguish Kerensky''s 1917 overthrow from the broader civil war and clarify that its conventional end was 1922, with some sources citing 1923."}',550,490,1,NULL,NULL,NULL,'gpt-5.6-luna');
INSERT INTO node_attempts VALUES(1622,'b463bf7d-686e-46ed-947d-aed62338affb','answer',0,'{"answer":"The premise is inaccurate: Kerensky was overthrown in October 1917 and did not lead the main anti-Bolshevik forces. The Russian Civil War is generally considered to have ended in 1922, though some accounts extend it to 1923.","supporting_entity_ids":["alexander_kerensky","russian_civil_war","bolsheviks"],"confidence":0.98,"confidence_bucket":"high"}',618,167,1,NULL,NULL,NULL,'gpt-5.6-luna');
