INSERT INTO node_attempts VALUES(1821,'1553d161-7fb5-4d94-b095-d2eba7b8ff27','gather',0,'{"facts":[{"entity_id":"british_jet_medium_bomber","fact":"The English Electric Canberra was Britain’s first jet-powered medium bomber, designed and flown after World War II; its first flight was in 1949.","relevance":1.0},{"entity_id":"british_jet_medium_bomber","fact":"Canberra entered Royal Air Force service in 1951, so it could not have been operational in any World War II theatre.","relevance":0.98},{"entity_id":"south_west_pacific_theatre","fact":"The South West Pacific theatre was a World War II command theatre, chiefly covering operations in New Guinea, the Netherlands East Indies, the Philippines, and nearby areas from 1942 to 1945.","relevance":0.76},{"entity_id":"south_west_pacific_theatre","fact":"No British first-generation jet-powered medium bomber was used operationally in the South West Pacific theatre during its World War II existence.","relevance":0.98},{"entity_id":"world_war_ii","fact":"World War II ended in 1945, four years before the Canberra prototype first flew and six years before RAF service entry.","relevance":0.98},{"entity_id":"world_war_ii","fact":"Early British jet aircraft that did see late-war operational service, such as the Gloster Meteor, were fighters rather than medium bombers.","relevance":0.82}],"fact_count":6,"coverage_notes":"The premise is chronologically inconsistent: the relevant British jet medium bomber was the postwar English Electric Canberra, not a World War II South West Pacific aircraft."}',557,575,1,NULL,NULL,NULL,'gpt-5.6-terra');
INSERT INTO node_attempts VALUES(1822,'1553d161-7fb5-4d94-b095-d2eba7b8ff27','answer',0,'{"answer":"None. The English Electric Canberra was Britain’s first jet-powered medium bomber, but it first flew in 1949 and entered RAF service in 1951, after World War II; no such bomber served in the South West Pacific theatre.","supporting_entity_ids":["british_jet_medium_bomber","south_west_pacific_theatre","world_war_ii"],"confidence":0.99,"confidence_bucket":"high"}',624,93,1,NULL,NULL,NULL,'gpt-5.6-terra');
