INSERT INTO node_attempts VALUES(2374,'00cf91a8-0eb4-4d59-b0ac-d9f377bdd31d','gather',0,'{"facts": [{"entity_id": "kiss_and_tell_film", "fact": "Kiss and Tell is a 1945 American comedy film in which the character Corliss Archer was portrayed by Shirley Temple.", "relevance": 1.0}, {"entity_id": "corliss_archer", "fact": "Corliss Archer is a fictional character created by F. Hugh Herbert, appearing in the 1945 film Kiss and Tell, played by Shirley Temple.", "relevance": 0.9}, {"entity_id": "shirley_temple", "fact": "Shirley Temple, who played Corliss Archer in Kiss and Tell, later became a diplomat and politician.", "relevance": 1.0}, {"entity_id": "shirley_temple", "fact": "Shirley Temple served as United States Ambassador to Ghana from 1974 to 1976.", "relevance": 1.0}, {"entity_id": "shirley_temple", "fact": "Shirley Temple later served as United States Ambassador to Czechoslovakia from 1989 to 1992.", "relevance": 0.9}, {"entity_id": "shirley_temple", "fact": "Shirley Temple also held the position of Chief of Protocol of the United States from 1976 to 1977.", "relevance": 0.9}], "fact_count": 6, "coverage_notes": "Covers the film, the character, and Shirley Temple''s government positions as ambassador and Chief of Protocol."}',794,497,1,NULL,NULL,NULL,'claude-sonnet-5');
INSERT INTO node_attempts VALUES(2375,'00cf91a8-0eb4-4d59-b0ac-d9f377bdd31d','answer',0,'{"answer":"Shirley Temple, who portrayed Corliss Archer in the 1945 film Kiss and Tell, held several U.S. government positions: she served as United States Ambassador to Ghana (1974–1976), Chief of Protocol of the United States (1976–1977), and United States Ambassador to Czechoslovakia (1989–1992).","supporting_entity_ids":["shirley_temple","kiss_and_tell_film","corliss_archer"],"confidence":0.95,"confidence_bucket":"high"}',901,179,1,NULL,NULL,NULL,'claude-sonnet-5');
