INSERT INTO node_attempts VALUES(2481,'57e7d9f9-e0cc-4c61-a4f0-7e1043f50f08','gather',0,replace('{\n  "facts": [\n    {"entity_id": "tunnels_and_trolls", "fact": "Tunnels and Trolls (T&T) was one of the first tabletop role-playing games, published in 1975, and pioneered the format of single-player ''solo adventures'' that could be played without a Game Master.", "relevance": 0.95},\n    {"entity_id": "tunnels_and_trolls", "fact": "In T&T terminology, a scripted adventure module—whether played solo or as a group dungeon crawl—is commonly referred to as a ''solo adventure'' or simply an ''adventure'', with many published as numbered paragraph-based gamebooks.", "relevance": 0.9},\n    {"entity_id": "tunnels_and_trolls", "fact": "T&T''s solo adventures use a ''choose your path'' paragraph format similar to Choose Your Own Adventure books, where players make decisions and roll dice to determine outcomes.", "relevance": 0.7},\n    {"entity_id": "ken_st_andre", "fact": "Ken St. Andre designed Tunnels and Trolls in 1975 as an alternative to Dungeons & Dragons, aiming for simpler rules accessible to new players.", "relevance": 0.8},\n    {"entity_id": "ken_st_andre", "fact": "Ken St. Andre is credited with creating the first true solo adventure gamebook format in tabletop RPGs through Tunnels and Trolls, most notably with ''Buffalo Castle'' in 1976.", "relevance": 0.9}\n  ],\n  "fact_count": 5,\n  "coverage_notes": "Facts cover the origin, design, and terminology of adventures in Tunnels and Trolls, and Ken St. Andre''s role in creating the solo adventure format."\n}','\n',char(10)),775,1033,1,NULL,NULL,NULL,'claude-sonnet-5');
INSERT INTO node_attempts VALUES(2482,'57e7d9f9-e0cc-4c61-a4f0-7e1043f50f08','answer',0,'{"answer":"In Tunnels and Trolls, a scripted adventure module is called a ''solo adventure'' (or simply an ''adventure''), a paragraph-based gamebook format using a choose-your-path structure with dice rolls, first exemplified by Ken St. Andre''s ''Buffalo Castle'' in 1976.","supporting_entity_ids":["tunnels_and_trolls","ken_st_andre"],"confidence":0.85,"confidence_bucket":"high"}',992,165,1,NULL,NULL,NULL,'claude-sonnet-5');
