INSERT INTO node_attempts VALUES(2492,'56222b4c-3b77-4318-b1c0-00a1ec13a067','gather',0,replace('```json\n{\n  "facts": [\n    {\n      "entity_id": "loiseau_blanc",\n      "fact": "L''Oiseau Blanc (The White Bird) was a French biplane that famously disappeared on 8 May 1927 while attempting to make the first nonstop transatlantic flight from Paris to New York.",\n      "relevance": 1.0\n    },\n    {\n      "entity_id": "loiseau_blanc",\n      "fact": "The aircraft was a Levasseur PL.8 biplane, specially modified for the long-distance transatlantic attempt, and it vanished after leaving Le Bourget Airport near Paris.",\n      "relevance": 0.8\n    },\n    {\n      "entity_id": "french_ace_pilot",\n      "fact": "Charles Nungesser, a French World War I flying ace credited with 43 aerial victories, piloted L''Oiseau Blanc on its ill-fated transatlantic attempt.",\n      "relevance": 1.0\n    },\n    {\n      "entity_id": "french_ace_pilot",\n      "fact": "Nungesser was accompanied by François Coli, an experienced aviator and navigator, who served as co-pilot and navigator on the flight.",\n      "relevance": 0.9\n    },\n    {\n      "entity_id": "french_ace_pilot",\n      "fact": "Both Nungesser and Coli disappeared without a trace after their aircraft was last sighted over Newfoundland, and their fate remains one of aviation''s enduring mysteries.",\n      "relevance": 0.7\n    }\n  ],\n  "fact_count": 5,\n  "coverage_notes": "Covers the identity of L''Oiseau Blanc aircraft and the French ace pilot Charles Nungesser (with navigator François Coli) who flew it in the 1927 transatlantic attempt."\n}\n```','\n',char(10)),771,618,0,'markdown_wrap','["markdown_wrap"]','[{"category": "markdown_wrap", "loc": "", "type": "json_invalid", "msg": "Invalid JSON: expected value at line 1 column 1"}]','claude-sonnet-5');
