INSERT INTO node_attempts VALUES(2494,'56222b4c-3b77-4318-b1c0-00a1ec13a067','answer',0,'{"answer":"L''Oiseau Blanc was flown by French World War I flying ace Charles Nungesser, who piloted the plane, accompanied by navigator François Coli, during their attempted nonstop transatlantic flight from Paris to New York on 8 May 1927. Both vanished without a trace after being last seen over Newfoundland.","supporting_entity_ids":["loiseau_blanc","french_ace_pilot"],"confidence":0.95,"confidence_bucket":"high"}',942,168,1,NULL,NULL,NULL,'claude-sonnet-5');
