INSERT INTO node_attempts VALUES(2507,'13dc383b-e49d-4ed9-ba4f-9990fdcfa849','gather',0,replace('{\n  "facts": [\n    {\n      "entity_id": "alexander_kerensky",\n      "fact": "Alexander Kerensky led the Russian Provisional Government in 1917 and was overthrown when the Bolsheviks seized power in the October Revolution.",\n      "relevance": 0.8\n    },\n    {\n      "entity_id": "alexander_kerensky",\n      "fact": "After his overthrow, Kerensky fled Russia and lived in exile, never regaining political power as the Bolsheviks consolidated control during the civil war.",\n      "relevance": 0.7\n    },\n    {\n      "entity_id": "bolsheviks",\n      "fact": "The Bolsheviks, led by Vladimir Lenin, seized power in October 1917 and fought the Russian Civil War against the anti-communist White movement and other opposing forces.",\n      "relevance": 0.9\n    },\n    {\n      "entity_id": "bolsheviks",\n      "fact": "The Bolsheviks'' Red Army ultimately defeated the White forces and other opponents, securing control over most of the former Russian Empire by the end of the civil war.",\n      "relevance": 0.9\n    },\n    {\n      "entity_id": "russian_civil_war",\n      "fact": "The Russian Civil War was fought from 1917 (or 1918, depending on the source) to 1923, primarily between the Bolshevik Red Army and the anti-Bolshevik White Army.",\n      "relevance": 1.0\n    },\n    {\n      "entity_id": "russian_civil_war",\n      "fact": "The main phase of the war effectively ended in 1920 with the defeat of the major White armies, though sporadic fighting, particularly in the Far East, continued until October 1922, and the last resistance was suppressed by June 1923.",\n      "relevance": 1.0\n    }\n  ],\n  "fact_count": 6,\n  "coverage_notes": "Facts cover Kerensky''s overthrow, the Bolsheviks'' rise and victory, and the timeline/end of the Russian Civil War, directly addressing when the war concluded."\n}','\n',char(10)),804,698,1,NULL,NULL,NULL,'claude-sonnet-5');
