INSERT INTO node_attempts VALUES(2548,'95362cfc-dea8-4618-8c15-4a033e5d2ded','gather',0,replace('{\n  "facts": [\n    {\n      "entity_id": "back_to_mono",\n      "fact": "Back to Mono (1958-1969) is a box set of Phil Spector productions released in 1991, compiling many of his famous ''Wall of Sound'' hits.",\n      "relevance": 0.8\n    },\n    {\n      "entity_id": "first_track_song",\n      "fact": "The first track on the Back to Mono box set is ''Da Doo Ron Ron'' by The Crystals.",\n      "relevance": 0.6\n    },\n    {\n      "entity_id": "first_track_song",\n      "fact": "The actual first track that opens the Back to Mono box set is ''To Know Him Is to Love Him'' by The Teddy Bears, a song written by Phil Spector.",\n      "relevance": 0.95\n    },\n    {\n      "entity_id": "tombstone_inspiration",\n      "fact": "''To Know Him Is to Love Him'' was written by Phil Spector, inspired by the epitaph on his father''s tombstone, which read ''To Know Him Was to Love Him.''",\n      "relevance": 1.0\n    },\n    {\n      "entity_id": "tombstone_inspiration",\n      "fact": "Phil Spector''s father, Benjamin Spector, died in 1949, and the phrase from his gravestone at Beth David Cemetery inspired the 1958 hit song.",\n      "relevance": 0.9\n    }\n  ],\n  "fact_count": 5,\n  "coverage_notes": "Facts confirm the song ''To Know Him Is to Love Him'' opens Back to Mono, was inspired by a tombstone epitaph, and was written by Phil Spector."\n}','\n',char(10)),804,564,1,NULL,NULL,NULL,'claude-sonnet-5');
