INSERT INTO node_attempts VALUES(2558,'3ad51d93-4d79-479b-bf4b-bfb749db9bb5','gather',0,replace('{\n  "facts": [\n    {\n      "entity_id": "british_jet_bomber",\n      "fact": "The English Electric Canberra, first flown in 1949, is generally regarded as Britain''s first jet-powered medium bomber, entering RAF service in 1951.",\n      "relevance": 0.9\n    },\n    {\n      "entity_id": "british_jet_bomber",\n      "fact": "No British jet bomber saw combat during World War II; British jet aircraft in WWII were limited to fighters like the Gloster Meteor, used only in Europe against V-1 flying bombs.",\n      "relevance": 0.85\n    },\n    {\n      "entity_id": "british_jet_bomber",\n      "fact": "The Canberra later served in conflicts such as the Malayan Emergency and Suez Crisis, but was never deployed in the Pacific theatre, which had ended by the time it entered service.",\n      "relevance": 0.7\n    },\n    {\n      "entity_id": "south_west_pacific_theatre",\n      "fact": "The South West Pacific theatre of World War II (1942–1945) encompassed the Philippines, Australia, Dutch East Indies, and New Guinea, primarily under Allied command led by General Douglas MacArthur.",\n      "relevance": 0.6\n    },\n    {\n      "entity_id": "south_west_pacific_theatre",\n      "fact": "Air operations in the South West Pacific during WWII relied exclusively on propeller-driven aircraft such as B-25 Mitchells, B-24 Liberators, and Australian Beauforts, as jet aircraft were not deployed there.",\n      "relevance": 0.8\n    },\n    {\n      "entity_id": "world_war_ii",\n      "fact": "World War II (1939–1945) saw the first operational use of jet aircraft, but these were limited to a small number of German and British types used almost exclusively in the European theatre.",\n      "relevance": 0.7\n    },\n    {\n      "entity_id": "world_war_ii",\n      "fact": "The war ended in the Pacific in August 1945, before any British jet bomber (like the Canberra) had been developed or entered service, making the premise of a British jet bomber in the WWII South West Pacific theatre historically inaccurate.",\n      "relevance": 0.9\n    }\n  ],\n  "fact_count": 7,\n  "coverage_notes": "Facts clarify that no British jet-powered medium bomber actually operated in the WWII South West Pacific theatre, as Britain''s first such bomber (Canberra) entered service after the war ended."\n}','\n',char(10)),811,1209,1,NULL,NULL,NULL,'claude-sonnet-5');
INSERT INTO node_attempts VALUES(2559,'3ad51d93-4d79-479b-bf4b-bfb749db9bb5','answer',0,'{"answer":"There was no such aircraft. Britain''s first jet-powered medium bomber, the English Electric Canberra, did not fly until 1949 and entered RAF service in 1951—years after WWII ended. No British jet bomber saw combat in WWII; British jets in that war were fighters (e.g., Gloster Meteor) used only in Europe. All Allied air operations in the South West Pacific theatre relied on propeller-driven aircraft. The premise of the question is historically inaccurate.","supporting_entity_ids":["british_jet_bomber","south_west_pacific_theatre","world_war_ii"],"confidence":0.95,"confidence_bucket":"high"}',1143,229,0,'length_bound','["length_bound"]','[{"category": "length_bound", "loc": "answer", "type": "string_too_long", "msg": "String should have at most 400 characters"}]','claude-sonnet-5');
INSERT INTO node_attempts VALUES(2560,'3ad51d93-4d79-479b-bf4b-bfb749db9bb5','answer',1,'{"answer":"No such aircraft existed. Britain''s first jet medium bomber, the Canberra, flew in 1949 and entered service in 1951, after WWII ended. British WWII jets were only fighters used in Europe; all South West Pacific air operations used propeller-driven planes. The premise is historically inaccurate.","supporting_entity_ids":["british_jet_bomber","south_west_pacific_theatre","world_war_ii"],"confidence":0.95,"confidence_bucket":"high"}',1512,171,1,NULL,NULL,NULL,'claude-sonnet-5');
