INSERT INTO node_attempts VALUES(2661,'b70f67ba-9dcf-4099-91cb-24fd30a43ae1','answer',0,'{"answer": "Charles Nungesser, a French flying ace and adventurer from World War I, piloted L''Oiseau Blanc. He was accompanied by navigator François Coli on the attempted first non-stop transatlantic flight from Paris to New York in May 1927.", "supporting_entity_ids": ["french_ace_pilot", "loiseau_blanc"], "confidence": 0.97, "confidence_bucket": "high"}',813,149,1,NULL,NULL,NULL,'claude-opus-4-8');
