INSERT INTO node_attempts VALUES(2725,'7d8a12e3-cd2c-4059-bf4c-e37b9a08e81d','gather',0,'{"facts":[{"entity_id":"three_m","fact":"3M is a diversified industrial company for which operating margin is generally a useful measure of core operating efficiency and profitability.","relevance":0.92},{"entity_id":"three_m","fact":"3M''s FY2022 operating performance was affected by substantial litigation, impairment, exit, restructuring, and growth-investment costs.","relevance":0.96},{"entity_id":"operating_margin","fact":"Operating margin declined or came under pressure in FY2022 as higher SG&A and special-item expenses reduced operating profitability relative to sales.","relevance":0.95},{"entity_id":"operating_margin","fact":"Operating margin remains useful for 3M, but FY2022 reported margin should be interpreted alongside adjusted results because unusual charges distorted comparability.","relevance":0.98},{"entity_id":"fy2022","fact":"FY2022 included an approximately $1.2 billion pre-tax second-quarter charge primarily related to steps toward resolving Combat Arms Earplugs litigation.","relevance":0.99},{"entity_id":"fy2022","fact":"FY2022 also included costs for exiting PFAS manufacturing, exiting Russia, divestiture-related restructuring, and continued investment in key growth initiatives.","relevance":0.97},{"entity_id":"selling_general_admin","fact":"SG&A as a percentage of sales increased in 2022 compared with the prior year, putting pressure on operating margin.","relevance":0.99},{"entity_id":"selling_general_admin","fact":"The SG&A increase reflected higher special-item costs and growth investments, partly offset by restructuring benefits and ongoing general 3M cost management.","relevance":0.98}],"fact_count":8,"coverage_notes":"Covers the margin direction, major FY2022 cost drivers, and why reported operating margin needs adjusted interpretation."}',722,529,1,NULL,NULL,NULL,'gpt-5.6-luna');
INSERT INTO node_attempts VALUES(2726,'7d8a12e3-cd2c-4059-bf4c-e37b9a08e81d','answer',0,'{"answer":"3M’s FY2022 operating margin declined because SG&A as a percentage of sales increased, driven by an approximately $1.2 billion Combat Arms Earplugs litigation charge, PFAS manufacturing exit impairments, Russia exit costs, divestiture-related restructuring, and growth investments. Restructuring benefits and cost management partly offset these pressures. Operating margin remains useful for 3M, but reported FY2022 results should be assessed alongside adjusted results because unusual charges reduced comparability.","supporting_entity_ids":["three_m","operating_margin","selling_general_admin","fy2022"],"confidence":0.98,"confidence_bucket":"high"}',827,185,0,'length_bound','["length_bound"]','[{"category": "length_bound", "loc": "answer", "type": "string_too_long", "msg": "String should have at most 400 characters"}]','gpt-5.6-luna');
INSERT INTO node_attempts VALUES(2727,'7d8a12e3-cd2c-4059-bf4c-e37b9a08e81d','answer',1,'{"answer":"3M’s FY2022 operating margin declined as SG&A rose relative to sales. Key pressures included the approximately $1.2 billion Combat Arms Earplugs litigation charge, PFAS and Russia exit costs, divestiture restructuring, and growth investments. Cost management partly offset them. Margin remains useful, but unusual charges warrant reviewing adjusted results.","supporting_entity_ids":["three_m","operating_margin","selling_general_admin","fy2022"],"confidence":0.98,"confidence_bucket":"high"}',1057,127,1,NULL,NULL,NULL,'gpt-5.6-luna');
