INSERT INTO node_attempts VALUES(2758,'3ce67db9-6dd8-42b2-b80b-fee9aa613bd2','gather',0,'{"facts":[{"entity_id":"adobe_inc","fact":"Adobe''s operating income was $6,098 million in FY2022, compared with $5,802 million in FY2021 and $4,237 million in FY2020.","relevance":0.96},{"entity_id":"operating_margin","fact":"Adobe''s operating margin was approximately 34.6% in FY2022, down from 36.8% in FY2021 but up from 32.9% in FY2020.","relevance":1.0},{"entity_id":"adobe_inc","fact":"Adobe therefore did not have a consistently improving operating margin profile as of FY2022; margin expansion through FY2021 partially reversed in FY2022.","relevance":1.0},{"entity_id":"operating_margin","fact":"Operating margin is a useful metric for Adobe because it measures profitability after operating costs, although it should be interpreted alongside growth and investment spending.","relevance":0.88}],"fact_count":4,"coverage_notes":"The facts calculate and compare FY2020-FY2022 margins and explain the metric''s relevance."}',809,377,1,NULL,NULL,NULL,'gpt-5.6-luna');
INSERT INTO node_attempts VALUES(2759,'3ce67db9-6dd8-42b2-b80b-fee9aa613bd2','answer',0,'{"answer":"No. Adobe’s operating margin was 32.9% in FY2020, rose to 36.8% in FY2021, then declined to 34.6% in FY2022. Thus, it was not consistently improving as of FY2022, despite operating income increasing. Operating margin remains useful for Adobe because it captures profitability after operating costs, but should be considered alongside revenue growth and investment spending.","supporting_entity_ids":["adobe_inc","operating_margin"],"confidence":0.98,"confidence_bucket":"high"}',836,165,1,NULL,NULL,NULL,'gpt-5.6-luna');
