INSERT INTO node_attempts VALUES(2761,'e3f35d89-d887-4b6f-85ac-82d487286d49','gather',0,'{"facts":[{"entity_id":"adobe_inc","fact":"Adobe generated net cash from operating activities of $7,838 million in FY2022, compared with $7,230 million in FY2021 and $5,727 million in FY2020.","relevance":0.98},{"entity_id":"adobe_inc","fact":"Adobe''s free cash flow, calculated as operating cash flow less purchases of property and equipment, was $7,396 million in FY2022 versus $6,882 million in FY2021 and $5,308 million in FY2020.","relevance":1.0},{"entity_id":"free_cash_flow_conversion","fact":"Using free cash flow divided by net income, Adobe''s conversion improved to approximately 155.5% in FY2022 from 142.7% in FY2021 and 100.9% in FY2020.","relevance":1.0},{"entity_id":"fiscal_year_2022","fact":"FY2022 net income was $4,756 million, while operating cash flow was $7,838 million and capital expenditures were $442 million.","relevance":0.96}],"fact_count":4,"coverage_notes":"The filing supports an improving FY2022 free cash flow conversion trend when conversion is defined as free cash flow divided by net income."}',1009,413,1,NULL,NULL,NULL,'gpt-5.6-luna');
INSERT INTO node_attempts VALUES(2762,'e3f35d89-d887-4b6f-85ac-82d487286d49','answer',0,'{"answer":"Yes. Adobe’s free cash flow conversion improved to approximately 155.5% in FY2022, up from 142.7% in FY2021 and 100.9% in FY2020, based on free cash flow divided by net income.","supporting_entity_ids":["adobe_inc","free_cash_flow_conversion","fiscal_year_2022"],"confidence":0.98,"confidence_bucket":"high"}',1045,134,1,NULL,NULL,NULL,'gpt-5.6-luna');
