INSERT INTO node_attempts VALUES(2774,'f80e9a53-7df6-49b4-9ae5-9f8d49fda036','gather',0,'{"facts":[{"entity_id":"amazon_com","fact":"Amazon reported FY2017 cost of sales of $111,934 million in its consolidated statements of operations.","relevance":1.0},{"entity_id":"amazon_com","fact":"Amazon''s balance sheet reported accounts payable of $21,991 million and inventory of $11,461 million for FY2016, and accounts payable of $34,616 million and inventory of $16,047 million for FY2017.","relevance":1.0},{"entity_id":"days_payable_outstanding","fact":"Using the defined formula, DPO equals 365 × [(21,991 + 34,616) / 2] ÷ [111,934 + (16,047 − 11,461)] = 88.66 days.","relevance":1.0},{"entity_id":"fiscal_year_2017","fact":"The FY2017 calculation uses the year ended December 31, 2017, with FY2016 balance-sheet amounts used to compute average accounts payable and inventory change.","relevance":0.9}],"fact_count":4,"coverage_notes":"Includes the required FY2016 and FY2017 balance-sheet inputs, FY2017 cost of sales, and the complete rounded DPO calculation."}',1050,1075,1,NULL,NULL,NULL,'gpt-5.6-luna');
INSERT INTO node_attempts VALUES(2775,'f80e9a53-7df6-49b4-9ae5-9f8d49fda036','answer',0,'{"answer":"Amazon’s FY2017 days payable outstanding was 88.66 days, calculated as 365 × [($21,991M + $34,616M) / 2] ÷ [$111,934M + ($16,047M − $11,461M)].","supporting_entity_ids":["amazon_com","days_payable_outstanding","fiscal_year_2017"],"confidence":0.99,"confidence_bucket":"high"}',1068,157,1,NULL,NULL,NULL,'gpt-5.6-luna');
