INSERT INTO node_attempts VALUES(2777,'dd458b0c-3189-4a34-b65f-298ea9ab62c9','gather',0,'{"facts":[{"entity_id":"amazon_com","fact":"Amazon.com, Inc.''s consolidated statements of operations report total net sales for fiscal years 2016 and 2017.","relevance":0.92},{"entity_id":"total_net_sales","fact":"Total net sales were $135,987 million in FY2016 and $177,866 million in FY2017.","relevance":1.0},{"entity_id":"fy2016","fact":"Amazon reported FY2016 total net sales of $135,987 million, consisting of net product sales and net service sales.","relevance":0.98},{"entity_id":"fy2017","fact":"Amazon reported FY2017 total net sales of $177,866 million, consisting of net product sales and net service sales.","relevance":0.98},{"entity_id":"total_net_sales","fact":"The year-over-year revenue change from FY2016 to FY2017 is calculated as (($177,866 - $135,987) / $135,987) × 100.","relevance":1.0},{"entity_id":"total_net_sales","fact":"Using total net sales as revenue, Amazon''s FY2016-to-FY2017 year-over-year increase was 30.8% rounded to one decimal place.","relevance":1.0}],"fact_count":6,"coverage_notes":"Facts identify the relevant total net sales line items, their FY2016 and FY2017 values, and the requested year-over-year calculation."}',1018,457,1,NULL,NULL,NULL,'gpt-5.6-luna');
INSERT INTO node_attempts VALUES(2778,'dd458b0c-3189-4a34-b65f-298ea9ab62c9','answer',0,'{"answer":"Amazon''s revenue increased by 30.8% from FY2016 to FY2017, calculated as (($177,866 million − $135,987 million) ÷ $135,987 million) × 100.","supporting_entity_ids":["total_net_sales","fy2016","fy2017","amazon_com"],"confidence":0.99,"confidence_bucket":"high"}',1059,136,1,NULL,NULL,NULL,'gpt-5.6-luna');
