INSERT INTO node_attempts VALUES(2786,'5515eefe-13c6-4e28-8c4e-c3f5b07e3e07','gather',0,'{"facts":[{"entity_id":"amcor_plc","fact":"Amcor plc disclosed the substitution of an issuer for certain guaranteed senior notes in its July 1, 2022 Form 8-K filing.","relevance":1.0},{"entity_id":"amcor_finance_usa","fact":"Amcor Finance (USA), Inc. was the former issuer of the 3.625% Guaranteed Senior Notes due 2026 and 4.500% Guaranteed Senior Notes due 2028.","relevance":0.95},{"entity_id":"amcor_flexibles_north_america","fact":"Amcor Flexibles North America, Inc. became the substitute issuer and assumed the former issuer’s covenants under the applicable indentures.","relevance":1.0},{"entity_id":"amcor_flexibles_north_america","fact":"The substitution was documented through supplemental indentures covering both the 2016 and 2019 note indentures.","relevance":0.9},{"entity_id":"form_8k_filing","fact":"The Form 8-K reported supplemental indentures entered into on June 30, 2022, relating to the issuer substitution and covenant assumption.","relevance":1.0},{"entity_id":"form_8k_filing","fact":"The filing’s key agenda was to formalize the replacement of the former issuer for existing and new 2026 and 2028 senior notes.","relevance":1.0}],"fact_count":6,"coverage_notes":"The facts identify the filing’s central purpose: replacing Amcor Finance (USA) as issuer with Amcor Flexibles North America and documenting the related debt obligations."}',1100,443,1,NULL,NULL,NULL,'gpt-5.6-luna');
