INSERT INTO node_attempts VALUES(2789,'78352683-aa79-4c4b-913f-3ee2bf7f69fa','gather',0,'{"facts":[{"entity_id":"amcor_plc","fact":"Amcor plc''s quick ratio improved from approximately 0.53 in FY2022 to 0.57 in FY2023, based on cash plus trade receivables divided by total current liabilities.","relevance":1.0},{"entity_id":"amcor_plc","fact":"The quick ratio is a relevant liquidity measure for an analyst assessing whether Amcor can cover near-term obligations without relying on inventory sales.","relevance":0.86},{"entity_id":"quick_ratio","fact":"The quick ratio generally measures highly liquid current assets, such as cash and receivables, relative to current liabilities and excludes inventory.","relevance":1.0},{"entity_id":"quick_ratio","fact":"Using the filing figures, the calculation is (cash plus trade receivables) divided by total current liabilities.","relevance":1.0},{"entity_id":"fy2023","fact":"For FY2023, Amcor reported cash and cash equivalents of $689 million, trade receivables of $1,875 million, and total current liabilities of $4,476 million.","relevance":1.0},{"entity_id":"fy2023","fact":"Amcor''s FY2023 quick ratio is approximately ($689 million plus $1,875 million) divided by $4,476 million, or 0.57.","relevance":1.0},{"entity_id":"fy2022","fact":"For FY2022, Amcor reported cash and cash equivalents of $775 million, trade receivables of $1,935 million, and total current liabilities of $5,103 million.","relevance":1.0},{"entity_id":"fy2022","fact":"Amcor''s FY2022 quick ratio is approximately ($775 million plus $1,935 million) divided by $5,103 million, or 0.53.","relevance":1.0}],"fact_count":8,"coverage_notes":"The filing supports a standard quick-ratio comparison using cash and trade receivables against total current liabilities; inventory and prepaid assets are excluded."}',1157,729,1,NULL,NULL,NULL,'gpt-5.6-luna');
INSERT INTO node_attempts VALUES(2790,'78352683-aa79-4c4b-913f-3ee2bf7f69fa','answer',0,'{"answer":"Amcor’s quick ratio improved from approximately 0.53 in FY2022 to 0.57 in FY2023. It is a relevant analyst measure because it indicates whether the company can cover near-term liabilities using cash and receivables without relying on inventory sales.","supporting_entity_ids":["amcor_plc","quick_ratio","fy2022","fy2023"],"confidence":0.98,"confidence_bucket":"high"}',1308,141,1,NULL,NULL,NULL,'gpt-5.6-luna');
