INSERT INTO node_attempts VALUES(2798,'8710391c-9cda-4bc9-a77b-c39d53339470','gather',0,'{"facts":[{"entity_id":"amcor_plc","fact":"Amcor plc reported gross profit of $2,725 million on net sales of $14,694 million in FY2023.","relevance":1.0},{"entity_id":"amcor_plc","fact":"Amcor''s FY2023 gross margin was approximately 18.5%, down from approximately 19.4% in FY2022 and 21.2% in FY2021.","relevance":1.0},{"entity_id":"gross_margin","fact":"Gross margin is a useful metric for Amcor, but it should be interpreted alongside volume, pricing, product mix, and raw-material pass-through effects typical of packaging companies.","relevance":0.9},{"entity_id":"gross_margin","fact":"Based on the reported figures, Amcor does not have an improving gross-margin profile through FY2023; its gross margin declined for the second consecutive year.","relevance":1.0},{"entity_id":"fy2023","fact":"For the year ended June 30, 2023, Amcor''s gross profit decreased by $95 million while net sales increased by $150 million versus FY2022.","relevance":0.95}],"fact_count":5,"coverage_notes":"The filing data directly supports a declining, rather than improving, gross-margin trend; the metric remains informative but requires operating-context interpretation."}',656,415,1,NULL,NULL,NULL,'gpt-5.6-luna');
