INSERT INTO node_attempts VALUES(2801,'e58174eb-b1d7-4561-9f95-62d07b4686d0','gather',0,'{"facts":[{"entity_id":"amcor","fact":"At December 31, 2022, AMCOR reported total restructuring costs liability of $93 million, down from $118 million at June 30, 2022.","relevance":1.0},{"entity_id":"restructuring_liability","fact":"The $93 million balance consisted of $81 million for employee costs, $2 million for fixed-asset-related costs, and $10 million for other costs.","relevance":1.0},{"entity_id":"restructuring_liability","fact":"The liability represents anticipated obligations arising from AMCOR’s restructuring activities, primarily employee-related costs and related payments.","relevance":0.95},{"entity_id":"amcor","fact":"During the six months ended December 31, 2022, AMCOR recorded $2 million of net restructuring charges, paid $25 million in cash, and reversed $2 million of unused amounts.","relevance":0.9}],"fact_count":4,"coverage_notes":"Facts explain the liability’s purpose, composition, and change through the Q2 FY2023 close."}',644,372,1,NULL,NULL,NULL,'gpt-5.6-luna');
INSERT INTO node_attempts VALUES(2802,'e58174eb-b1d7-4561-9f95-62d07b4686d0','answer',0,'{"answer":"As of Q2 FY2023 (December 31, 2022), AMCOR’s $93 million restructuring liability represented anticipated obligations from restructuring activities. It primarily covered employee-related costs ($81 million), plus fixed-asset-related costs ($2 million) and other costs ($10 million). The balance declined from $118 million at June 30, 2022, after $25 million of cash payments and a $2 million reversal, partly offset by $2 million of new charges.","supporting_entity_ids":["amcor","restructuring_liability"],"confidence":0.98,"confidence_bucket":"high"}',663,184,0,'length_bound','["length_bound"]','[{"category": "length_bound", "loc": "answer", "type": "string_too_long", "msg": "String should have at most 400 characters"}]','gpt-5.6-luna');
