INSERT INTO node_attempts VALUES(2822,'26cc97ce-e5a3-45ea-9632-8e071e5e00f0','gather',0,'{"facts":[{"entity_id":"mmm","fact":"3M''s SG&A as a percentage of sales increased in 2022, creating downward pressure on operating margin versus the prior year.","relevance":0.98},{"entity_id":"mmm","fact":"Higher SG&A reflected approximately $1.2 billion of pre-tax Combat Arms Earplugs litigation costs, PFAS-exit impairments, Russia-exit costs, divestiture restructuring charges, and growth investments.","relevance":1.0},{"entity_id":"mmm","fact":"Restructuring benefits and ongoing cost management partially offset the higher special-item and investment costs.","relevance":0.9},{"entity_id":"operating_margin","fact":"Operating margin remains a useful metric for 3M because it shows how operating costs changed relative to sales, but FY2022 should be interpreted with special litigation and exit-related charges in mind.","relevance":0.96},{"entity_id":"fy2022","fact":"The principal FY2022 margin headwind described was an increase in SG&A as a percent of sales, driven largely by special items rather than only recurring operating costs.","relevance":0.98}],"fact_count":5,"coverage_notes":"The filing excerpt supports a FY2022 operating-margin decline driven by higher SG&A and identifies the major cost drivers and partial offsets."}',705,344,1,NULL,NULL,NULL,'gpt-5.6-terra');
INSERT INTO node_attempts VALUES(2823,'26cc97ce-e5a3-45ea-9632-8e071e5e00f0','answer',0,'{"answer":"3M’s FY2022 operating margin was pressured by higher SG&A as a percentage of sales. The main drivers were approximately $1.2 billion of Combat Arms Earplugs litigation costs, PFAS-exit impairments, Russia-exit costs, divestiture-related restructuring charges, and growth investments. Restructuring benefits and cost management partly offset these impacts. Operating margin remains useful, but FY2022 was materially affected by special items.","supporting_entity_ids":["mmm","operating_margin","fy2022"],"confidence":0.96,"confidence_bucket":"high"}',745,123,0,'length_bound','["length_bound"]','[{"category": "length_bound", "loc": "answer", "type": "string_too_long", "msg": "String should have at most 400 characters"}]','gpt-5.6-terra');
INSERT INTO node_attempts VALUES(2824,'26cc97ce-e5a3-45ea-9632-8e071e5e00f0','answer',1,'{"answer":"FY2022 operating margin was pressured by higher SG&A relative to sales, chiefly from about $1.2B of Combat Arms Earplugs litigation costs, PFAS and Russia exit costs, divestiture restructuring, and growth investment. Cost management partly offset this. Margin remains useful but was distorted by special items.","supporting_entity_ids":["mmm","operating_margin","fy2022"],"confidence":0.96,"confidence_bucket":"high"}',964,97,1,NULL,NULL,NULL,'gpt-5.6-terra');
