INSERT INTO node_attempts VALUES(2845,'4857ab5d-1abe-41ac-b2c6-2ea2202abf85','gather',0,'{"facts":[{"entity_id":"activision_blizzard","fact":"Activision Blizzard reported total net revenues of $6,489 million in 2019, $7,500 million in 2018, and $7,017 million in 2017.","relevance":1.0},{"entity_id":"capital_expenditures","fact":"Capital expenditures were $178 million in 2019, $151 million in 2018, and $119 million in 2017, as reported in the cash flow information.","relevance":1.0},{"entity_id":"revenue","fact":"Total FY2017-FY2019 revenue was $21,006 million, calculated as $6,489 million plus $7,500 million plus $7,017 million.","relevance":0.95},{"entity_id":"fy2017_fy2019","fact":"Total FY2017-FY2019 capital expenditures were $448 million; $448 million divided by $21,006 million of revenue equals 2.1327%, or 2.1% rounded to one decimal place.","relevance":1.0}],"fact_count":4,"coverage_notes":"Uses total net revenues from the income statement and annual capital expenditures from cash flow information; the three-year capex-to-revenue ratio is 2.1%."}',1062,677,1,NULL,NULL,NULL,'gpt-5.6-terra');
