INSERT INTO node_attempts VALUES(2851,'ac5e0018-ded6-4cb2-bde8-679e024982f1','gather',0,'{"facts":[{"entity_id":"adobe_systems","fact":"Adobe Systems Incorporated reported consolidated operating income in its income statement for fiscal years 2015 and 2016.","relevance":0.92},{"entity_id":"operating_income","fact":"Unadjusted operating income was $1,493.602 million in FY2016 and $903.095 million in FY2015.","relevance":1.0},{"entity_id":"fy2015","fact":"FY2015 operating income was $903,095 thousand, the comparison base for the year-over-year calculation.","relevance":0.98},{"entity_id":"fy2016","fact":"FY2016 operating income was $1,493,602 thousand; the year-over-year increase was ($1,493,602 - $903,095) / $903,095 = 65.4%.","relevance":1.0}],"fact_count":4,"coverage_notes":"The income statement provides unadjusted operating income for both fiscal years. Calculating the change relative to FY2015 yields a 65.4% increase."}',1198,304,1,NULL,NULL,NULL,'gpt-5.6-terra');
INSERT INTO node_attempts VALUES(2852,'ac5e0018-ded6-4cb2-bde8-679e024982f1','answer',0,'{"answer":"Adobe''s unadjusted operating income increased by 65.4% year over year, from $903.095 million in FY2015 to $1,493.602 million in FY2016: (($1,493.602M − $903.095M) / $903.095M) × 100 = 65.4%.","supporting_entity_ids":["adobe_systems","operating_income","fy2015","fy2016"],"confidence":0.99,"confidence_bucket":"high"}',1171,112,1,NULL,NULL,NULL,'gpt-5.6-terra');
