INSERT INTO node_attempts VALUES(2858,'b6dac2d0-7af4-4c2f-8d8e-fb02014b868a','gather',0,'{"facts":[{"entity_id":"adobe_inc","fact":"Adobe reported operating income of $6.098 billion in FY2022, compared with $5.802 billion in FY2021 and $4.237 billion in FY2020.","relevance":0.96},{"entity_id":"adobe_inc","fact":"Adobe''s FY2022 revenue was $17.606 billion, up from $15.785 billion in FY2021 and $12.868 billion in FY2020.","relevance":0.91},{"entity_id":"operating_margin","fact":"Adobe''s FY2022 operating margin was approximately 34.6%, calculated as $6.098 billion of operating income divided by $17.606 billion of revenue.","relevance":1.0},{"entity_id":"operating_margin","fact":"Adobe''s operating margin was approximately 36.8% in FY2021 and 32.9% in FY2020; thus, FY2022 declined about 2.1 percentage points year over year.","relevance":1.0},{"entity_id":"operating_margin","fact":"Operating margin is a useful profitability metric for Adobe because it measures operating income relative to revenue before interest and taxes, enabling comparison of core operating efficiency across years.","relevance":0.89},{"entity_id":"fy2022","fact":"As of FY2022, Adobe''s operating-margin profile was not consistently improving: margin remained above FY2020 but fell from the higher FY2021 level.","relevance":0.99}],"fact_count":6,"coverage_notes":"Calculations use reported total revenue and operating income for FY2020 through FY2022; the metric remains informative for Adobe''s software business."}',827,460,1,NULL,NULL,NULL,'gpt-5.6-terra');
INSERT INTO node_attempts VALUES(2859,'b6dac2d0-7af4-4c2f-8d8e-fb02014b868a','answer',0,'{"answer":"No. Adobe’s operating-margin profile was not consistently improving as of FY2022: operating margin was about 32.9% in FY2020, 36.8% in FY2021, and 34.6% in FY2022. Although FY2022 remained above FY2020, it declined roughly 2.1 percentage points year over year. Operating margin is useful for Adobe because it gauges core operating profitability relative to revenue across periods.","supporting_entity_ids":["operating_margin","adobe_inc","fy2022"],"confidence":0.99,"confidence_bucket":"high"}',930,128,1,NULL,NULL,NULL,'gpt-5.6-terra');
