INSERT INTO node_attempts VALUES(2861,'0ff8ec91-2d45-48d0-92dd-b09db36a2378','gather',0,'{"facts":[{"entity_id":"adobe","fact":"Adobe reported net cash provided by operating activities of $7.838 billion in FY2022, up from $7.230 billion in FY2021 and $5.727 billion in FY2020.","relevance":0.95},{"entity_id":"adobe","fact":"Adobe''s property and equipment purchases were $442 million in FY2022, versus $348 million in FY2021 and $419 million in FY2020.","relevance":0.91},{"entity_id":"free_cash_flow_conversion","fact":"Using free cash flow as operating cash flow less property and equipment purchases, Adobe generated approximately $7.396 billion in FY2022, $6.882 billion in FY2021, and $5.308 billion in FY2020.","relevance":0.98},{"entity_id":"free_cash_flow_conversion","fact":"Free-cash-flow-to-net-income conversion improved from about 100.9% in FY2020 to 142.7% in FY2021 and 155.5% in FY2022, based on the filing figures.","relevance":1.0},{"entity_id":"fy2022","fact":"Adobe FY2022 ended December 2, 2022; net income was $4.756 billion, slightly below FY2021 net income of $4.822 billion while free cash flow increased.","relevance":0.9}],"fact_count":5,"coverage_notes":"Cash flow and capital-expenditure figures support an improving free-cash-flow conversion trend through FY2022, despite slightly lower FY2022 net income."}',1003,422,1,NULL,NULL,NULL,'gpt-5.6-terra');
INSERT INTO node_attempts VALUES(2862,'0ff8ec91-2d45-48d0-92dd-b09db36a2378','answer',0,'{"answer":"Yes. Adobe’s free-cash-flow conversion improved each year: approximately 100.9% in FY2020, 142.7% in FY2021, and 155.5% in FY2022. FY2022 free cash flow rose to about $7.396 billion while net income was $4.756 billion.","supporting_entity_ids":["free_cash_flow_conversion","adobe","fy2022"],"confidence":0.99,"confidence_bucket":"high"}',1095,152,1,NULL,NULL,NULL,'gpt-5.6-terra');
