INSERT INTO node_attempts VALUES(2873,'a83a2956-07d0-4b16-a388-d77e1d15c1b8','gather',0,'{"facts":[{"entity_id":"amazon_com","fact":"Amazon reported accounts payable of $25,309 million at December 31, 2016 and $34,616 million at December 31, 2017.","relevance":1.0},{"entity_id":"amazon_com","fact":"Amazon reported inventories of $11,461 million in FY2016 and $16,047 million in FY2017, a $4,586 million increase.","relevance":0.96},{"entity_id":"amazon_com","fact":"Amazon''s FY2017 cost of sales was $111,934 million in the consolidated statements of operations.","relevance":1.0},{"entity_id":"fy2017","fact":"For FY2017, the DPO denominator is $116,520 million: $111,934 million cost of sales plus the $4,586 million inventory increase.","relevance":0.98},{"entity_id":"days_payable_outstanding","fact":"Average accounts payable for FY2016-FY2017 was $29,962.5 million, calculated as ($25,309 million + $34,616 million) / 2.","relevance":0.98},{"entity_id":"days_payable_outstanding","fact":"FY2017 DPO equals 365 × $29,962.5 million / $116,520 million = 93.86 days, rounded to two decimal places.","relevance":1.0}],"fact_count":6,"coverage_notes":"Uses FY2016 and FY2017 balance-sheet accounts payable and inventory, plus FY2017 cost of sales from the P&L, under the stated DPO formula."}',1046,643,1,NULL,NULL,NULL,'gpt-5.6-terra');
