INSERT INTO node_attempts VALUES(2888,'e68bc7bd-6db7-4267-9069-e47d64e8ef53','gather',0,'{"facts":[{"entity_id":"amcor_plc","fact":"Amcor plc''s quick ratio improved to approximately 0.57 at June 30, 2023, from approximately 0.53 at June 30, 2022, using cash plus trade receivables divided by total current liabilities.","relevance":1.0},{"entity_id":"quick_ratio","fact":"The quick ratio conventionally excludes inventories and prepaid expenses; it measures immediate liquidity as cash and cash equivalents plus receivables, divided by current liabilities.","relevance":0.96},{"entity_id":"fy2023","fact":"For FY2023, cash and cash equivalents were $689 million and trade receivables were $1,875 million, totaling $2,564 million of quick assets; current liabilities were $4,476 million.","relevance":0.94},{"entity_id":"fy2022","fact":"For FY2022, cash and cash equivalents were $775 million and trade receivables were $1,935 million, totaling $2,710 million of quick assets; current liabilities were $5,103 million.","relevance":0.94}],"fact_count":4,"coverage_notes":"The quick ratio is a relevant, standard liquidity measure for Amcor, though it should be considered alongside cash flow, debt, and working-capital trends."}',1157,394,1,NULL,NULL,NULL,'gpt-5.6-terra');
INSERT INTO node_attempts VALUES(2889,'e68bc7bd-6db7-4267-9069-e47d64e8ef53','answer',0,'{"answer":"AMCOR''s quick ratio improved: approximately 0.57 in FY2023 ($2,564m quick assets / $4,476m current liabilities) versus approximately 0.53 in FY2022 ($2,710m / $5,103m). This is a relevant liquidity metric for AMCOR.","supporting_entity_ids":["amcor_plc","quick_ratio","fy2023","fy2022"],"confidence":0.99,"confidence_bucket":"high"}',1183,103,1,NULL,NULL,NULL,'gpt-5.6-terra');
