INSERT INTO node_attempts VALUES(2897,'d48a0959-f099-4bd1-ae3a-c5b7ef34f4cd','gather',0,'{"facts":[{"entity_id":"amcor_plc","fact":"Amcor plc reported FY2023 net sales of $14,694 million, cost of sales of $11,969 million, and gross profit of $2,725 million.","relevance":1.0},{"entity_id":"amcor_plc","fact":"Amcor''s gross profit declined from $2,820 million in FY2022 to $2,725 million in FY2023, despite net sales increasing from $14,544 million to $14,694 million.","relevance":0.98},{"entity_id":"gross_margin","fact":"Amcor''s gross margin was approximately 18.5% in FY2023 ($2,725 million gross profit divided by $14,694 million net sales).","relevance":1.0},{"entity_id":"gross_margin","fact":"Amcor''s gross margin declined from approximately 21.2% in FY2021 to 19.4% in FY2022 and 18.5% in FY2023, indicating a deteriorating rather than improving profile.","relevance":1.0},{"entity_id":"gross_margin","fact":"Gross margin is a useful metric for Amcor because it is a packaging manufacturer whose profitability is materially affected by production, materials, and other cost-of-sales inputs relative to customer pricing.","relevance":0.85},{"entity_id":"fy2023","fact":"FY2023 refers to Amcor''s fiscal year ended June 30, 2023.","relevance":0.72}],"fact_count":6,"coverage_notes":"FY2023 gross margin was calculated from the provided income-statement amounts and compared with FY2022 and FY2021 to assess the trend."}',656,420,1,NULL,NULL,NULL,'gpt-5.6-terra');
