INSERT INTO node_attempts VALUES(2917,'7d6d9e13-c087-4d50-ac17-d223a4ef97af','gather',0,'{"facts":[{"entity_id":"three_m_company","fact":"3M reported FY2022 net sales of $34.229 billion and year-end total assets of approximately $46.455 billion.","relevance":1.0},{"entity_id":"three_m_company","fact":"3M''s FY2022 capital expenditures were approximately $1.749 billion, while year-end net property, plant and equipment was approximately $9.178 billion.","relevance":0.98},{"entity_id":"capital_intensity","fact":"Using total assets divided by sales, 3M''s FY2022 capital-intensity ratio was about 1.36, meaning it employed roughly $1.36 of assets for each $1 of annual sales.","relevance":0.97},{"entity_id":"capital_intensity","fact":"Alternative operating measures were approximately 5.1% for capital expenditures as a percentage of sales and 26.8% for net property, plant and equipment as a percentage of sales.","relevance":0.95},{"entity_id":"fy2022_data","fact":"FY2022 sales and capital expenditures cover the year ended December 31, 2022, whereas total assets and net property, plant and equipment are balances at that date.","relevance":0.89},{"entity_id":"fy2022_data","fact":"The FY2022 ratios indicate a meaningful physical-asset base, but the 5.1% capital-expenditure-to-sales ratio does not by itself establish that 3M was exceptionally capital intensive.","relevance":0.93}],"fact_count":6,"coverage_notes":"FY2022 supports describing 3M as moderately capital intensive: assets exceeded annual sales and net PP&E was substantial, while capital spending was only about 5.1% of sales. Industry comparisons would strengthen the conclusion."}',599,1356,1,NULL,NULL,NULL,'gpt-5.6-sol');
INSERT INTO node_attempts VALUES(2918,'7d6d9e13-c087-4d50-ac17-d223a4ef97af','answer',0,'{"answer":"Yes, but only moderately. In FY2022, 3M employed about $1.36 of total assets per $1 of sales, with net PP&E equal to 26.8% of sales. However, capital expenditures were only 5.1% of sales, so the data show a meaningful physical-asset base rather than an exceptionally capital-intensive business.","supporting_entity_ids":["three_m_company","capital_intensity","fy2022_data"],"confidence":0.94,"confidence_bucket":"high"}',707,111,1,NULL,NULL,NULL,'gpt-5.6-sol');
INSERT INTO node_attempts VALUES(2919,'7fcd3725-1112-4691-bd8a-75621b3682a2','identify',0,'{"entities":[{"name":"3M","entity_type":"organization","canonical_id":"three_m"},{"name":"Operating margin","entity_type":"concept","canonical_id":"operating_margin"},{"name":"FY2022","entity_type":"other","canonical_id":"fy2022"}],"question_type":"what","primary_entity_id":"three_m","entity_count":3}',745,141,1,NULL,NULL,NULL,'gpt-5.6-sol');
INSERT INTO node_attempts VALUES(2920,'7fcd3725-1112-4691-bd8a-75621b3682a2','gather',0,'{"facts":[{"entity_id":"three_m","fact":"3M’s FY2022 SG&A expense increased as a percentage of sales, putting downward pressure on reported operating margin.","relevance":1.0},{"entity_id":"three_m","fact":"The increase in SG&A was partly offset by restructuring benefits and ongoing company-wide cost management.","relevance":0.91},{"entity_id":"operating_margin","fact":"Operating margin declined primarily because of higher special-item costs, including an approximately $1.2 billion pre-tax charge related to steps toward resolving Combat Arms Earplugs litigation.","relevance":1.0},{"entity_id":"operating_margin","fact":"Additional margin headwinds included PFAS-exit impairment costs, Russia-exit costs, divestiture-related restructuring charges, and continued investment in key growth initiatives.","relevance":0.98},{"entity_id":"fy2022","fact":"For FY2022, reported operating margin remained a useful profitability metric for 3M, but it was materially distorted by litigation and other unusual charges.","relevance":0.97},{"entity_id":"fy2022","fact":"Assessing FY2022 underlying performance therefore also requires an adjusted operating margin that excludes significant special items, while recognizing that growth investments and ordinary cost management remain operating factors.","relevance":0.91}],"fact_count":6,"coverage_notes":"Covers the principal FY2022 margin headwinds, partial cost offsets, and why both reported and adjusted operating margins are informative for 3M."}',706,417,1,NULL,NULL,NULL,'gpt-5.6-sol');
INSERT INTO node_attempts VALUES(2921,'7fcd3725-1112-4691-bd8a-75621b3682a2','answer',0,'{"answer":"3M’s FY2022 reported operating margin declined mainly because SG&A rose as a percentage of sales, led by a roughly $1.2 billion pre-tax Combat Arms Earplugs litigation charge. PFAS and Russia exit costs, divestiture restructuring, and growth investments also weighed on margin, partly offset by restructuring benefits and cost controls. The metric remains useful, but adjusted margin better reflects underlying performance.","supporting_entity_ids":["three_m","operating_margin","fy2022"],"confidence":0.98,"confidence_bucket":"high"}',769,116,0,'length_bound','["length_bound"]','[{"category": "length_bound", "loc": "answer", "type": "string_too_long", "msg": "String should have at most 400 characters"}]','gpt-5.6-sol');
INSERT INTO node_attempts VALUES(2922,'7fcd3725-1112-4691-bd8a-75621b3682a2','answer',1,'{"answer":"3M’s FY2022 operating margin fell mainly because SG&A rose versus sales, led by a roughly $1.2 billion pre-tax Combat Arms Earplugs litigation charge. PFAS and Russia exit costs, divestiture restructuring, and growth investments also hurt margin, partly offset by restructuring benefits and cost controls. Operating margin remains useful, but adjusted margin better shows underlying performance.","supporting_entity_ids":["three_m","operating_margin","fy2022"],"confidence":0.98,"confidence_bucket":"high"}',981,128,1,NULL,NULL,NULL,'gpt-5.6-sol');
