INSERT INTO node_attempts VALUES(2932,'99d6dea4-377d-43ca-ab84-c4c46b33ee8a','answer',0,'{"answer":"As of Q2 2023, 3M’s exchange-registered debt securities were: 1.500% Notes due 2026 (MMM26), 1.750% Notes due 2030 (MMM30), and 1.500% Notes due 2031 (MMM31). All were registered on the New York Stock Exchange.","supporting_entity_ids":["three_m_company","debt_securities","national_securities_exchange","q2_2023"],"confidence":0.99,"confidence_bucket":"high"}',675,115,1,NULL,NULL,NULL,'gpt-5.6-sol');
