INSERT INTO node_attempts VALUES(2938,'b1cdfdb0-1521-4e50-b2c0-28d38702d856','gather',0,'{"facts":[{"entity_id":"activision_blizzard","fact":"Activision Blizzard''s consolidated financial statements report amounts in millions of dollars.","relevance":0.8},{"entity_id":"fixed_asset_turnover_ratio","fact":"FY2019 fixed asset turnover equals FY2019 revenue divided by average net PP&E for FY2018 and FY2019.","relevance":1.0},{"entity_id":"fixed_asset_turnover_ratio","fact":"Using the reported figures, the ratio is $6,489 million / $267.5 million = 24.26, rounded to two decimals.","relevance":1.0},{"entity_id":"property_plant_equipment","fact":"Net property and equipment was $253 million at December 31, 2019 and $282 million at December 31, 2018.","relevance":1.0},{"entity_id":"property_plant_equipment","fact":"Average FY2018-FY2019 net PP&E was ($282 million + $253 million) / 2 = $267.5 million.","relevance":1.0},{"entity_id":"fy2019_revenue","fact":"Activision Blizzard reported FY2019 consolidated net revenues of $6,489 million.","relevance":1.0}],"fact_count":6,"coverage_notes":"The facts cover the reported revenue and net PP&E balances, the required averaging calculation, and the resulting FY2019 fixed asset turnover ratio of 24.26."}',1164,438,1,NULL,NULL,NULL,'gpt-5.6-sol');
INSERT INTO node_attempts VALUES(2939,'b1cdfdb0-1521-4e50-b2c0-28d38702d856','answer',0,'{"answer":"Activision Blizzard’s FY2019 fixed asset turnover ratio was 24.26: $6,489 million ÷ [($282 million + $253 million) ÷ 2] = 24.26.","supporting_entity_ids":["fy2019_revenue","property_plant_equipment","fixed_asset_turnover_ratio","activision_blizzard"],"confidence":0.99,"confidence_bucket":"high"}',1176,90,1,NULL,NULL,NULL,'gpt-5.6-sol');
