INSERT INTO node_attempts VALUES(2941,'b16c67af-c477-46fb-b724-6386f7eb0123','gather',0,'{"facts":[{"entity_id":"activision_blizzard","fact":"Activision Blizzard reported total net revenues of $6,489 million in FY2019, $7,500 million in FY2018, and $7,017 million in FY2017.","relevance":1.0},{"entity_id":"activision_blizzard","fact":"The cash flow statement reports capital expenditures of $104 million in FY2019, $138 million in FY2018, and $155 million in FY2017, using the absolute values of the cash outflows.","relevance":1.0},{"entity_id":"capex_revenue_ratio","fact":"Capex as a percentage of revenue is calculated for each year as capital expenditures divided by total net revenues, multiplied by 100.","relevance":0.99},{"entity_id":"capex_revenue_ratio","fact":"The annual ratios are approximately 1.6% for FY2019, 1.8% for FY2018, and 2.2% for FY2017.","relevance":0.98},{"entity_id":"fy2017_fy2019_average","fact":"The three-year average is the arithmetic mean of the FY2017, FY2018, and FY2019 annual capex-to-revenue percentages.","relevance":0.99},{"entity_id":"fy2017_fy2019_average","fact":"Using the unrounded annual ratios, the FY2017–FY2019 average capex as a percentage of revenue is approximately 1.9%, rounded to one decimal place.","relevance":1.0}],"fact_count":6,"coverage_notes":"The facts include revenue from the statement of operations, capex from the cash flow statement, the annual ratios, and the resulting three-year average."}',1059,1721,1,NULL,NULL,NULL,'gpt-5.6-sol');
INSERT INTO node_attempts VALUES(2942,'b16c67af-c477-46fb-b724-6386f7eb0123','answer',0,'{"answer":"The FY2017–FY2019 average capex as a percentage of revenue was 1.9%, calculated as the arithmetic mean of 155/7,017, 138/7,500, and 104/6,489, multiplied by 100.","supporting_entity_ids":["activision_blizzard","capex_revenue_ratio","fy2017_fy2019_average"],"confidence":0.99,"confidence_bucket":"high"}',1156,98,1,NULL,NULL,NULL,'gpt-5.6-sol');
