INSERT INTO node_attempts VALUES(2947,'81bc17ac-1c59-4416-9e41-d401cbc6fa4e','gather',0,'{"facts":[{"entity_id":"adobe_systems","fact":"Adobe Systems Incorporated reports its consolidated income statement amounts in thousands of dollars, except per-share data.","relevance":0.85},{"entity_id":"operating_income","fact":"The year-over-year change is calculated as (FY2016 operating income − FY2015 operating income) ÷ FY2015 operating income × 100.","relevance":1.0},{"entity_id":"fy2015","fact":"Adobe''s unadjusted operating income for FY2015 was $903.095 million, as reported on the income statement.","relevance":1.0},{"entity_id":"fy2016","fact":"Adobe''s unadjusted operating income for FY2016 was $1,493.602 million, an increase of $590.507 million, or approximately 65.4%, from FY2015.","relevance":1.0}],"fact_count":4,"coverage_notes":"The facts provide the reported FY2015 and FY2016 operating income figures, statement units, calculation method, and rounded year-over-year result."}',1201,281,1,NULL,NULL,NULL,'gpt-5.6-sol');
INSERT INTO node_attempts VALUES(2948,'81bc17ac-1c59-4416-9e41-d401cbc6fa4e','answer',0,'{"answer":"Adobe’s unadjusted operating income increased 65.4% year over year: (($1,493.602M − $903.095M) ÷ $903.095M) × 100 = 65.4%.","supporting_entity_ids":["operating_income","fy2015","fy2016"],"confidence":0.99,"confidence_bucket":"high"}',1173,84,1,NULL,NULL,NULL,'gpt-5.6-sol');
