INSERT INTO node_attempts VALUES(2981,'b529aa83-e468-4588-8b90-ce08ec863f53','gather',0,'{"facts":[{"entity_id":"amcor_8k_filing","fact":"The July 1, 2022 Form 8-K primarily reported the execution of supplemental indentures on June 30, 2022 to effect a substitution of issuer for Amcor''s outstanding guaranteed senior notes.","relevance":1.0},{"entity_id":"amcor_plc","fact":"Amcor plc was the parent company of both the former issuer and the substitute issuer involved in the transaction.","relevance":0.82},{"entity_id":"amcor_finance_usa","fact":"Amcor Finance (USA), Inc. was the former issuer of the relevant 3.625% Guaranteed Senior Notes due 2026 and 4.500% Guaranteed Senior Notes due 2028.","relevance":0.94},{"entity_id":"amcor_flexibles_na","fact":"Amcor Flexibles North America, Inc. replaced Amcor Finance (USA), Inc. as issuer and assumed the former issuer''s covenants and obligations under the applicable indentures.","relevance":0.98},{"entity_id":"issuer_substitution","fact":"The supplemental indentures implemented the issuer substitution for the 2026 and 2028 notes; the filing''s key agenda was documenting that change and the substitute issuer''s assumption of the indenture obligations.","relevance":1.0}],"fact_count":5,"coverage_notes":"The facts cover the filing''s central purpose, the two subsidiaries'' respective roles, Amcor plc''s relationship to them, and the affected senior-note indentures."}',1129,410,1,NULL,NULL,NULL,'gpt-5.6-sol');
