INSERT INTO node_attempts VALUES(2984,'42247558-e6f9-4d90-b5e1-2c9872b55d7b','gather',0,'{"facts":[{"entity_id":"amcor_plc","fact":"Amcor plc is a manufacturing and packaging company for which analysts can reasonably use the quick ratio to assess short-term liquidity without relying on inventory sales.","relevance":0.88},{"entity_id":"quick_ratio","fact":"Using (cash and cash equivalents + trade receivables) divided by total current liabilities, Amcor''s quick ratio increased from about 0.53 in FY2022 to about 0.57 in FY2023, indicating improvement.","relevance":1.0},{"entity_id":"fy2023","fact":"For FY2023, cash of $689 million plus trade receivables of $1,875 million totaled $2,564 million; divided by current liabilities of $4,476 million, the quick ratio was approximately 0.57.","relevance":0.99},{"entity_id":"fy2022","fact":"For FY2022, cash of $775 million plus trade receivables of $1,935 million totaled $2,710 million; divided by current liabilities of $5,103 million, the quick ratio was approximately 0.53.","relevance":0.99}],"fact_count":4,"coverage_notes":"The facts cover the ratio definition, both annual calculations, the direction of change, and why the metric is relevant to Amcor."}',1157,382,1,NULL,NULL,NULL,'gpt-5.6-sol');
INSERT INTO node_attempts VALUES(2985,'42247558-e6f9-4d90-b5e1-2c9872b55d7b','answer',0,'{"answer":"AMCOR’s quick ratio improved, rising from approximately 0.53 in FY2022 ($2,710M ÷ $5,103M) to 0.57 in FY2023 ($2,564M ÷ $4,476M). This is a relevant liquidity measure for a manufacturing and packaging company because it assesses its ability to meet current obligations without selling inventory.","supporting_entity_ids":["amcor_plc","quick_ratio","fy2023","fy2022"],"confidence":0.99,"confidence_bucket":"high"}',1190,117,1,NULL,NULL,NULL,'gpt-5.6-sol');
