INSERT INTO node_attempts VALUES(2987,'3f05eb20-eb3d-4c8e-8f4b-fffe05c3d032','gather',0,'{"facts":[{"entity_id":"amcor","fact":"Amcor''s fiscal year ends June 30, so acquisitions completed from July 1, 2022 through June 30, 2023 are classified as FY2023 transactions.","relevance":0.94},{"entity_id":"fy2023","fact":"On August 1, 2022, Amcor acquired 100% of a Czech flexible-packaging manufacturer for $59 million, including $5 million deferred until FY2024; it recognized $36 million of net assets and $23 million of goodwill.","relevance":1.0},{"entity_id":"fy2023","fact":"On March 17, 2023, Amcor acquired a medical-device packaging site in Shanghai, China for $60 million, including up to $20 million of contingent consideration; it recognized $21 million of net assets and $39 million of goodwill.","relevance":1.0},{"entity_id":"fy2023","fact":"On May 31, 2023, Amcor acquired a New Zealand manufacturer of automated protein-packaging machines for $45 million, including $13 million of contingent consideration.","relevance":1.0},{"entity_id":"major_acquisitions","fact":"All three FY2023 acquisitions—the Czech plant, Shanghai medical-device packaging site, and New Zealand packaging-machine manufacturer—were assigned to Amcor''s Flexibles reportable segment.","relevance":0.93},{"entity_id":"fy2022","fact":"The supplied filing excerpt does not identify or provide terms for any acquisition completed during FY2022, which ran from July 1, 2021 through June 30, 2022.","relevance":0.78},{"entity_id":"fy2021","fact":"The supplied filing excerpt does not identify or provide terms for any acquisition completed during FY2021, which ran from July 1, 2020 through June 30, 2021.","relevance":0.78}],"fact_count":7,"coverage_notes":"The excerpt supports three FY2023 acquisitions with transaction values and terms. Because evidence for FY2022 and FY2021 was not included, no acquisitions for those years are asserted."}',992,1383,1,NULL,NULL,NULL,'gpt-5.6-sol');
