INSERT INTO node_attempts VALUES(2993,'e72af209-9006-49a0-b2cc-579b08673d35','gather',0,'{"facts":[{"entity_id":"amcor_plc","fact":"Amcor''s net sales increased from $12.861 billion in FY2021 to $14.544 billion in FY2022 and $14.694 billion in FY2023.","relevance":0.9},{"entity_id":"amcor_plc","fact":"Amcor''s gross profit decreased from $2.820 billion in FY2022 to $2.725 billion in FY2023 despite a modest increase in net sales.","relevance":0.98},{"entity_id":"gross_margin","fact":"Gross margin, calculated as gross profit divided by net sales, was approximately 21.2% in FY2021, 19.4% in FY2022, and 18.5% in FY2023.","relevance":1.0},{"entity_id":"gross_margin","fact":"The three-year trend is deteriorating rather than improving, with gross margin contracting about 2.7 percentage points from FY2021 to FY2023 and 0.8 point in FY2023 alone.","relevance":1.0},{"entity_id":"fy2023","fact":"For FY2023, Amcor reported net sales of $14.694 billion, cost of sales of $11.969 billion, and gross profit of $2.725 billion.","relevance":0.97},{"entity_id":"fy2023","fact":"Gross margin remains a useful operating metric for Amcor because it is a manufacturing and packaging company, although raw-material pass-through pricing, product mix, and currency movements can affect comparability and should be considered alongside operating margins.","relevance":0.9}],"fact_count":6,"coverage_notes":"The filing data show that Amcor did not have an improving gross margin profile as of FY2023: its margin declined in each of the two latest year-over-year comparisons."}',656,508,1,NULL,NULL,NULL,'gpt-5.6-sol');
INSERT INTO node_attempts VALUES(2994,'e72af209-9006-49a0-b2cc-579b08673d35','answer',0,'{"answer":"No. Amcor’s gross margin deteriorated from about 21.2% in FY2021 to 19.4% in FY2022 and 18.5% in FY2023—a decline of roughly 2.7 percentage points over two years. Gross margin is useful for this packaging manufacturer, but raw-material pass-through pricing, product mix, and currency effects can affect comparability.","supporting_entity_ids":["amcor_plc","gross_margin","fy2023"],"confidence":0.99,"confidence_bucket":"high"}',786,116,1,NULL,NULL,NULL,'gpt-5.6-sol');
