INSERT INTO node_attempts VALUES(3278,'fcd60942-f3e5-4491-80e9-91f6e3b36336','gather',0,replace('{\n  "facts": [\n    {\n      "entity_id": "three_m",\n      "fact": "3M reported FY2022 net sales of $34,229 million, a decline from $35,355 million in 2021.",\n      "relevance": 0.7\n    },\n    {\n      "entity_id": "three_m",\n      "fact": "3M is a diversified industrial manufacturer with significant investments in property, plant, and equipment used to produce goods across multiple segments including safety, industrial, healthcare, and consumer products.",\n      "relevance": 0.65\n    },\n    {\n      "entity_id": "three_m",\n      "fact": "Historically, 3M has maintained substantial capital expenditures (typically $1.5-1.8 billion annually) relative to its revenue to support manufacturing operations, R&D, and global production facilities.",\n      "relevance": 0.6\n    },\n    {\n      "entity_id": "fy2022",\n      "fact": "FY2022 net sales for 3M were $34,229 million, down approximately 3.2% from FY2021''s $35,355 million.",\n      "relevance": 0.5\n    },\n    {\n      "entity_id": "fy2022",\n      "fact": "The provided context does not include capital expenditure, PP&E, or depreciation figures for FY2022, limiting direct calculation of capital intensity ratios like CapEx/Sales or PP&E/Assets.",\n      "relevance": 0.6\n    },\n    {\n      "entity_id": "capital_intensity",\n      "fact": "Capital intensity is typically measured by ratios such as capital expenditures as a percentage of revenue, or fixed assets (PP&E) relative to total assets; higher ratios indicate more capital-intensive businesses.",\n      "relevance": 0.8\n    },\n    {\n      "entity_id": "capital_intensity",\n      "fact": "Manufacturing-heavy companies like 3M, which produce physical goods across diverse segments (adhesives, abrasives, electronics, healthcare products), generally require significant fixed asset investment, a hallmark of capital-intensive industries.",\n      "relevance": 0.7\n    }\n  ],\n  "fact_count": 7,\n  "coverage_notes": "Context only provides net sales figures; lacks CapEx, PP&E, or depreciation data needed to directly quantify capital intensity for FY2022, so analysis relies on general industry characteristics."\n}','\n',char(10)),858,797,1,NULL,NULL,NULL,'claude-sonnet-5');
INSERT INTO node_attempts VALUES(3279,'fcd60942-f3e5-4491-80e9-91f6e3b36336','answer',0,replace('{\n  "answer": "Yes, 3M qualifies as a capital-intensive business. Although FY2022 filing data provided here only shows net sales ($34,229M, down 3.2% from $35,355M in 2021) without explicit CapEx, PP&E, or depreciation figures, 3M''s business model as a diversified manufacturer of adhesives, abrasives, electronics, safety, and healthcare products inherently requires substantial fixed asset investment. Historically, 3M has spent $1.5-1.8 billion annually on capital expenditures (roughly 4-5% of revenue), consistent with capital-intensive manufacturing industries that rely on large-scale production facilities, equipment, and global manufacturing footprints.",\n  "supporting_entity_ids": ["three_m", "fy2022", "capital_intensity"],\n  "confidence": 0.62,\n  "confidence_bucket": "medium"\n}','\n',char(10)),1162,305,0,'length_bound','["length_bound"]','[{"category": "length_bound", "loc": "answer", "type": "string_too_long", "msg": "String should have at most 400 characters"}]','claude-sonnet-5');
INSERT INTO node_attempts VALUES(3280,'fcd60942-f3e5-4491-80e9-91f6e3b36336','answer',1,replace('{\n  "answer": "Yes, 3M is capital-intensive. FY2022 filing data shows only net sales ($34,229M, down 3.2% from 2021) without CapEx/PP&E figures, but 3M''s diversified manufacturing model (adhesives, electronics, healthcare) historically requires $1.5-1.8B annual CapEx (~4-5% of revenue), typical of capital-intensive industries.",\n  "supporting_entity_ids": ["three_m", "fy2022", "capital_intensity"],\n  "confidence": 0.62,\n  "confidence_bucket": "medium"\n}','\n',char(10)),1614,205,1,NULL,NULL,NULL,'claude-sonnet-5');
