INSERT INTO node_attempts VALUES(3283,'89d5a568-f69f-4a28-8758-7f3f59e7cd17','gather',0,replace('{\n  "facts": [\n    {\n      "entity_id": "sga_expense",\n      "fact": "SG&A as a percent of sales increased in 2022 versus 2021, pressuring operating margin.",\n      "relevance": 0.95\n    },\n    {\n      "entity_id": "sga_expense",\n      "fact": "The increase was driven by a ~$1.2 billion pre-tax charge in Q2 2022 for Combat Arms Earplugs litigation resolution steps.",\n      "relevance": 0.95\n    },\n    {\n      "entity_id": "sga_expense",\n      "fact": "Additional SG&A pressure came from impairment costs tied to exiting PFAS manufacturing, costs from exiting Russia, and divestiture-related restructuring charges.",\n      "relevance": 0.9\n    },\n    {\n      "entity_id": "sga_expense",\n      "fact": "These cost increases were partially offset by restructuring benefits and ongoing general cost management, as well as continued investment in growth initiatives.",\n      "relevance": 0.7\n    },\n    {\n      "entity_id": "operating_margin",\n      "fact": "3M''s operating margin declined in FY2022 primarily due to elevated special item and litigation-related SG&A costs rather than core operational deterioration.",\n      "relevance": 0.9\n    },\n    {\n      "entity_id": "operating_margin",\n      "fact": "Because large one-time litigation and impairment charges heavily distort the SG&A line, operating margin is less useful for assessing underlying business performance in FY2022; adjusted or non-GAAP operating margin excluding these items would better reflect core profitability trends.",\n      "relevance": 0.85\n    },\n    {\n      "entity_id": "three_m",\n      "fact": "3M faced significant one-time legal and restructuring costs in 2022, including Combat Arms Earplugs litigation, PFAS exit, and Russia exit, which are not indicative of recurring operations.",\n      "relevance": 0.8\n    },\n    {\n      "entity_id": "fy2022",\n      "fact": "In FY2022, 3M''s reported margins were significantly affected by nonrecurring special items, making year-over-year margin comparisons less meaningful without adjustment.",\n      "relevance": 0.75\n    }\n  ],\n  "fact_count": 8,\n  "coverage_notes": "Facts cover SG&A drivers, their impact on operating margin, and caveat that reported margin is distorted by one-time litigation/impairment items in FY2022."\n}','\n',char(10)),1060,844,1,NULL,NULL,NULL,'claude-sonnet-5');
INSERT INTO node_attempts VALUES(3284,'89d5a568-f69f-4a28-8758-7f3f59e7cd17','answer',0,replace('{\n  "answer": "3M''s FY2022 operating margin declined mainly due to a sharp rise in SG&A as a percent of sales, driven by a ~$1.2 billion pre-tax charge for Combat Arms Earplugs litigation resolution steps, impairment costs from exiting PFAS manufacturing, costs from exiting Russia, and divestiture-related restructuring charges. These were only partially offset by restructuring benefits and general cost management. Because these are large, nonrecurring special items rather than reflections of core operating performance, reported operating margin is not a very useful metric for assessing underlying business trends in FY2022 without adjusting for these one-time charges; an adjusted/non-GAAP operating margin excluding litigation, impairment, and exit costs would better capture 3M''s true operational profitability.",\n  "supporting_entity_ids": ["sga_expense", "operating_margin", "three_m", "fy2022"],\n  "confidence": 0.85,\n  "confidence_bucket": "high"\n}','\n',char(10)),1373,339,0,'length_bound','["length_bound"]','[{"category": "length_bound", "loc": "answer", "type": "string_too_long", "msg": "String should have at most 400 characters"}]','claude-sonnet-5');
INSERT INTO node_attempts VALUES(3285,'89d5a568-f69f-4a28-8758-7f3f59e7cd17','answer',1,replace('{\n  "answer": "3M''s FY2022 operating margin fell mainly due to higher SG&A from a ~$1.2B Combat Arms Earplugs litigation charge, PFAS exit impairments, Russia exit costs, and divestiture restructuring, partly offset by cost management. These nonrecurring items distort results, so reported operating margin is less useful here; an adjusted margin excluding special items better reflects core profitability.",\n  "supporting_entity_ids": ["sga_expense", "operating_margin", "three_m", "fy2022"],\n  "confidence": 0.85,\n  "confidence_bucket": "high"\n}','\n',char(10)),1854,213,1,NULL,NULL,NULL,'claude-sonnet-5');
