INSERT INTO node_attempts VALUES(3288,'6be72226-5026-498b-8685-8312e827ea49','gather',0,replace('{\n  "facts": [\n    {\n      "entity_id": "three_m",\n      "fact": "3M''s total company organic sales growth in 2022 was 1.2%, while total sales change including acquisitions, divestitures, and translation was -3.2%.",\n      "relevance": 1.0\n    },\n    {\n      "entity_id": "consumer",\n      "fact": "Consumer segment organic sales declined by (0.9)% in 2022, the only segment with negative organic growth, excluding M&A and currency effects.",\n      "relevance": 1.0\n    },\n    {\n      "entity_id": "safety_and_industrial",\n      "fact": "Safety and Industrial segment had organic sales growth of 1.0% in 2022, positive but below the company average of 1.2%.",\n      "relevance": 0.5\n    },\n    {\n      "entity_id": "transportation_and_electronics",\n      "fact": "Transportation and Electronics segment had organic sales growth of 1.2% in 2022, in line with the total company organic growth.",\n      "relevance": 0.4\n    },\n    {\n      "entity_id": "health_care",\n      "fact": "Health Care segment had the highest organic sales growth in 2022 at 3.2%, well above the company average.",\n      "relevance": 0.4\n    }\n  ],\n  "fact_count": 5,\n  "coverage_notes": "Facts focus on organic sales growth (excluding acquisitions, divestitures, translation) by segment to identify which segment underperformed, revealing Consumer as the sole segment with negative organic growth."\n}','\n',char(10)),1060,518,1,NULL,NULL,NULL,'claude-sonnet-5');
INSERT INTO node_attempts VALUES(3289,'6be72226-5026-498b-8685-8312e827ea49','answer',0,replace('{\n  "answer": "Excluding M&A and currency translation effects, the Consumer segment was the only one with negative organic sales growth in 2022, declining (0.9)%, dragging down 3M''s overall organic growth of 1.2%. All other segments (Safety and Industrial +1.0%, Transportation and Electronics +1.2%, Health Care +3.2%) posted positive organic growth.",\n  "supporting_entity_ids": ["consumer", "three_m", "safety_and_industrial", "transportation_and_electronics", "health_care"],\n  "confidence": 0.95,\n  "confidence_bucket": "high"\n}','\n',char(10)),1080,213,1,NULL,NULL,NULL,'claude-sonnet-5');
