INSERT INTO node_attempts VALUES(3301,'f61b91d8-c79a-480d-8d5f-fcabe17347d2','gather',0,replace('```json\n{\n  "facts": [\n    {\n      "entity_id": "three_m",\n      "fact": "3M has increased its dividend for 65 consecutive years, indicating a long history of consistent capital return to shareholders.",\n      "relevance": 1.0\n    },\n    {\n      "entity_id": "three_m",\n      "fact": "3M is recognized as a ''Dividend King'' due to its multi-decade streak of annual dividend increases, reflecting strong and stable cash flow generation.",\n      "relevance": 0.9\n    },\n    {\n      "entity_id": "dividend_distribution",\n      "fact": "A 65-year streak of consecutive dividend increases demonstrates a highly stable and predictable dividend distribution trend, uninterrupted by economic downturns or recessions.",\n      "relevance": 1.0\n    },\n    {\n      "entity_id": "dividend_distribution",\n      "fact": "Consistent annual dividend growth over decades typically signals disciplined financial management and a commitment to returning value to shareholders regularly.",\n      "relevance": 0.85\n    }\n  ],\n  "fact_count": 4,\n  "coverage_notes": "Facts confirm 3M''s 65-year streak of dividend increases, directly supporting a stable, consistent dividend distribution trend."\n}\n```','\n',char(10)),783,436,0,'markdown_wrap','["markdown_wrap"]','[{"category": "markdown_wrap", "loc": "", "type": "json_invalid", "msg": "Invalid JSON: expected value at line 1 column 1"}]','claude-sonnet-5');
