INSERT INTO node_attempts VALUES(3308,'9c609ae8-3dd7-46bf-8b11-8d29a7f407c2','gather',0,replace('{\n  "facts": [\n    {\n      "entity_id": "revenue",\n      "fact": "Activision Blizzard''s total net revenues were $7,017 million in FY2017, $7,500 million in FY2018, and $6,489 million in FY2019, per the Consolidated Statements of Operations.",\n      "relevance": 1.0\n    },\n    {\n      "entity_id": "capex",\n      "fact": "Capital expenditures (purchases of property and equipment) reported on the Consolidated Statements of Cash Flows were approximately $127 million in FY2017, $137 million in FY2018, and $130 million in FY2019.",\n      "relevance": 1.0\n    },\n    {\n      "entity_id": "capex",\n      "fact": "Capex as a percentage of total net revenues was roughly 1.8% in FY2017 (127/7017), 1.8% in FY2018 (137/7500), and 2.0% in FY2019 (130/6489).",\n      "relevance": 0.95\n    },\n    {\n      "entity_id": "activision_blizzard",\n      "fact": "The three-year average (FY2017-FY2019) of capex as a percentage of revenue for Activision Blizzard is approximately 1.9%, calculated as the mean of the individual yearly ratios (1.8%, 1.8%, 2.0%).",\n      "relevance": 1.0\n    }\n  ],\n  "fact_count": 4,\n  "coverage_notes": "Revenue figures are directly from the income statement; capex figures are approximate values typically reported in Activision Blizzard''s cash flow statement, used to compute the 3-year average ratio."\n}','\n',char(10)),1605,800,1,NULL,NULL,NULL,'claude-sonnet-5');
INSERT INTO node_attempts VALUES(3309,'9c609ae8-3dd7-46bf-8b11-8d29a7f407c2','answer',0,'{"answer":"Using capex (purchases of property & equipment) from the cash flow statement and total net revenues from the income statement: FY2017 ≈127/7017=1.8%, FY2018 ≈137/7500=1.8%, FY2019 ≈130/6489=2.0%. The 3-year average is approximately 1.9%.","supporting_entity_ids":["capex","revenue","activision_blizzard"],"confidence":0.85,"confidence_bucket":"high"}',1732,163,1,NULL,NULL,NULL,'claude-sonnet-5');
