INSERT INTO node_attempts VALUES(3314,'b7e212f3-69ea-40e1-afc9-0e5d6fe7fbb9','gather',0,replace('{\n  "facts": [\n    {\n      "entity_id": "adobe_systems",\n      "fact": "Adobe''s Consolidated Statements of Income report Operating income of $1,493,602 thousand for FY2016 (ended December 2, 2016) and $903,095 thousand for FY2015 (ended November 27, 2015).",\n      "relevance": 1.0\n    },\n    {\n      "entity_id": "operating_income",\n      "fact": "Year-over-year change = (1,493,602 - 903,095) / 903,095 = 590,507 / 903,095 ≈ 0.6539, or approximately 65.4% increase in unadjusted operating income from FY2015 to FY2016.",\n      "relevance": 1.0\n    },\n    {\n      "entity_id": "operating_income",\n      "fact": "Operating income is calculated as Gross profit minus Total operating expenses; for FY2016 Gross profit was $5,034,522 thousand and Total operating expenses were $3,540,920 thousand, yielding $1,493,602 thousand; for FY2015 Gross profit was $4,051,194 thousand and Total operating expenses were $3,148,099 thousand, yielding $903,095 thousand.",\n      "relevance": 0.8\n    }\n  ],\n  "fact_count": 3,\n  "coverage_notes": "Facts directly pulled from Adobe''s FY2016 income statement provide the operating income figures for FY2015 and FY2016 needed to compute the year-over-year percentage change."\n}','\n',char(10)),1589,552,1,NULL,NULL,NULL,'claude-sonnet-5');
INSERT INTO node_attempts VALUES(3315,'b7e212f3-69ea-40e1-afc9-0e5d6fe7fbb9','answer',0,'{"answer":"Adobe''s operating income rose from $903,095 thousand in FY2015 to $1,493,602 thousand in FY2016, an increase of $590,507 thousand. This represents a year-over-year change of approximately +65.4% ((1,493,602 - 903,095) / 903,095 ≈ 0.6539).","supporting_entity_ids":["adobe_systems","operating_income"],"confidence":0.97,"confidence_bucket":"high"}',1727,159,1,NULL,NULL,NULL,'claude-sonnet-5');
