INSERT INTO node_attempts VALUES(3317,'8a3558b4-37c0-479a-b573-da7549a17ce3','gather',0,replace('{\n  "facts": [\n    {\n      "entity_id": "adobe_systems",\n      "fact": "Adobe''s total current liabilities as of December 1, 2017 were $3,527,457 thousand, per the consolidated balance sheet.",\n      "relevance": 0.9\n    },\n    {\n      "entity_id": "adobe_systems",\n      "fact": "Adobe''s cash flow from operations for FY2017 (fiscal year ended December 1, 2017) was approximately $2,913,999 thousand, as reported in the consolidated statement of cash flows.",\n      "relevance": 0.95\n    },\n    {\n      "entity_id": "operating_cash_flow_ratio",\n      "fact": "Operating cash flow ratio = Cash from operations / Total current liabilities; for Adobe FY2017 this equals $2,913,999K / $3,527,457K ≈ 0.83.",\n      "relevance": 1.0\n    }\n  ],\n  "fact_count": 3,\n  "coverage_notes": "Used balance sheet for total current liabilities and cash flow statement figure for operating cash flow to compute the ratio."\n}','\n',char(10)),1738,516,1,NULL,NULL,NULL,'claude-sonnet-5');
INSERT INTO node_attempts VALUES(3318,'8a3558b4-37c0-479a-b573-da7549a17ce3','answer',0,'{"answer":"Adobe''s FY2017 operating cash flow ratio was approximately 0.83, calculated as cash from operations ($2,913,999 thousand) divided by total current liabilities ($3,527,457 thousand).","supporting_entity_ids":["adobe_systems","operating_cash_flow_ratio"],"confidence":0.9,"confidence_bucket":"high"}',1754,133,1,NULL,NULL,NULL,'claude-sonnet-5');
