INSERT INTO node_attempts VALUES(3349,'4b2f24b6-ef3c-411a-b075-5994bd370d2a','gather',0,replace('{\n  "facts": [\n    {\n      "entity_id": "amcor",\n      "fact": "Amcor plc and Subsidiaries reports a Consolidated Balance Sheet as of June 30, 2020 and 2019, presenting Trade receivables, net as a line item under current assets.",\n      "relevance": 0.7\n    },\n    {\n      "entity_id": "fy2020",\n      "fact": "FY2020 balance sheet date is June 30, 2020, the reporting period column used to determine year-end figures.",\n      "relevance": 0.6\n    },\n    {\n      "entity_id": "net_accounts_receivable",\n      "fact": "Trade receivables, net is listed at $1,615.9 million as of June 30, 2020, compared to $1,864.3 million as of June 30, 2019.",\n      "relevance": 1.0\n    },\n    {\n      "entity_id": "net_accounts_receivable",\n      "fact": "This ''Trade receivables, net'' figure is the balance sheet''s net accounts receivable balance (net of allowance for doubtful accounts), representing the analyst-visible AR figure for FY2020 year-end.",\n      "relevance": 0.9\n    }\n  ],\n  "fact_count": 4,\n  "coverage_notes": "Facts extracted directly from the balance sheet line ''Trade receivables, net'' for FY2020 (June 30, 2020), which represents the net AR figure available to an analyst restricted to balance sheet data."\n}','\n',char(10)),1852,491,1,NULL,NULL,NULL,'claude-sonnet-5');
INSERT INTO node_attempts VALUES(3350,'4b2f24b6-ef3c-411a-b075-5994bd370d2a','answer',0,replace('{\n  "answer": "Amcor''s FY2020 year-end net accounts receivable (Trade receivables, net) as reported on the balance sheet was $1,615.9 million as of June 30, 2020, down from $1,864.3 million as of June 30, 2019.",\n  "supporting_entity_ids": ["amcor", "fy2020", "net_accounts_receivable"],\n  "confidence": 0.98,\n  "confidence_bucket": "high"\n}','\n',char(10)),1917,155,1,NULL,NULL,NULL,'claude-sonnet-5');
INSERT INTO node_attempts VALUES(3351,'0b8517ac-d46b-49c3-af72-b76f63e9f6fb','identify',0,replace('{\n  "entities": [\n    {"name": "Amcor plc", "entity_type": "organization", "canonical_id": "amcor_plc"},\n    {"name": "Amcor Finance (USA), Inc.", "entity_type": "organization", "canonical_id": "amcor_finance_usa"},\n    {"name": "Amcor Flexibles North America, Inc.", "entity_type": "organization", "canonical_id": "amcor_flexibles_north_america"},\n    {"name": "Form 8-K", "entity_type": "concept", "canonical_id": "form_8k"}\n  ],\n  "question_type": "what",\n  "primary_entity_id": "amcor_plc",\n  "entity_count": 4\n}','\n',char(10)),1648,241,1,NULL,NULL,NULL,'claude-sonnet-5');
INSERT INTO node_attempts VALUES(3352,'0b8517ac-d46b-49c3-af72-b76f63e9f6fb','gather',0,'{"facts": [{"entity_id": "amcor_plc", "fact": "Amcor plc is the parent company of both the Former Issuer (Amcor Finance (USA), Inc.) and the Substitute Issuer (Amcor Flexibles North America, Inc.), each of which are wholly-owned subsidiaries.", "relevance": 0.7}, {"entity_id": "amcor_finance_usa", "fact": "Amcor Finance (USA), Inc., the Former Issuer, entered into Supplemental Indentures on June 30, 2022 to substitute Amcor Flexibles North America, Inc. as the issuer of its 2026 and 2028 Guaranteed Senior Notes.", "relevance": 0.9}, {"entity_id": "amcor_flexibles_north_america", "fact": "Amcor Flexibles North America, Inc., the Substitute Issuer, assumed the covenants of the Former Issuer under the 2016 and 2019 Indentures via the Supplemental Indentures dated June 30, 2022, effectively replacing Amcor Finance (USA), Inc. as issuer of the 3.625% Notes due 2026 and 4.500% Notes due 2028.", "relevance": 0.95}, {"entity_id": "form_8k", "fact": "The 8-K filing dated July 1, 2022 discloses the entry into a Second Supplemental Indenture and First Supplemental Indenture on June 30, 2022, relating to the substitution of Amcor Flexibles North America, Inc. for Amcor Finance (USA), Inc. as issuer under existing note indentures.", "relevance": 1.0}, {"entity_id": "form_8k", "fact": "The key agenda of the filing is to document the issuer substitution and assumption of debt covenants for the 2026 and 2028 Guaranteed Senior Notes, following procedures established in a prior 2019 8-K filing regarding the New Notes exchange offer.", "relevance": 0.85}], "fact_count": 5, "coverage_notes": "Facts cover the purpose of the 8-K filing: substitution of issuer entities and assumption of note covenants dated June 30, 2022, filed July 1, 2022."}',1657,747,1,NULL,NULL,NULL,'claude-sonnet-5');
INSERT INTO node_attempts VALUES(3353,'0b8517ac-d46b-49c3-af72-b76f63e9f6fb','answer',0,'{"answer":"The 8-K filed July 1, 2022 (for the June 30, 2022 event) documents that Amcor Flexibles North America, Inc. was substituted for Amcor Finance (USA), Inc. as issuer under the 2016 and 2019 Indentures, via a Second Supplemental Indenture and a First Supplemental Indenture. The Substitute Issuer assumed all covenants of the Former Issuer for the 3.625% Guaranteed Senior Notes due 2026 and 4.500% Guaranteed Senior Notes due 2028, effectively transferring issuer responsibility while keeping Amcor plc as the ultimate parent guarantor.","supporting_entity_ids":["form_8k","amcor_finance_usa","amcor_flexibles_north_america","amcor_plc"],"confidence":0.92,"confidence_bucket":"high"}',1964,298,0,'length_bound','["length_bound"]','[{"category": "length_bound", "loc": "answer", "type": "string_too_long", "msg": "String should have at most 400 characters"}]','claude-sonnet-5');
INSERT INTO node_attempts VALUES(3354,'0b8517ac-d46b-49c3-af72-b76f63e9f6fb','answer',1,'{"answer":"The 8-K filed July 1, 2022 discloses that on June 30, 2022, Amcor Flexibles North America, Inc. was substituted for Amcor Finance (USA), Inc. as issuer under the 2016/2019 Indentures via Supplemental Indentures, assuming all covenants for the 3.625% Notes due 2026 and 4.500% Notes due 2028, with Amcor plc remaining parent guarantor.","supporting_entity_ids":["form_8k","amcor_finance_usa","amcor_flexibles_north_america","amcor_plc"],"confidence":0.92,"confidence_bucket":"high"}',2408,223,1,NULL,NULL,NULL,'claude-sonnet-5');
INSERT INTO node_attempts VALUES(3355,'3bab7f3c-ce53-4be1-9c54-6af46875ffb5','identify',0,replace('{\n  "entities": [\n    {\n      "name": "AMCOR",\n      "entity_type": "organization",\n      "canonical_id": "amcor"\n    },\n    {\n      "name": "FY2023",\n      "entity_type": "other",\n      "canonical_id": "fy2023"\n    },\n    {\n      "name": "FY2022",\n      "entity_type": "other",\n      "canonical_id": "fy2022"\n    },\n    {\n      "name": "Quick Ratio",\n      "entity_type": "concept",\n      "canonical_id": "quick_ratio"\n    }\n  ],\n  "question_type": "comparison",\n  "primary_entity_id": "amcor",\n  "entity_count": 4\n}','\n',char(10)),1795,233,1,NULL,NULL,NULL,'claude-sonnet-5');
INSERT INTO node_attempts VALUES(3356,'3bab7f3c-ce53-4be1-9c54-6af46875ffb5','gather',0,replace('{\n  "facts": [\n    {\n      "entity_id": "amcor",\n      "fact": "Amcor''s quick ratio (cash + trade receivables ÷ current liabilities) improved from approximately 0.53 in FY2022 to approximately 0.57 in FY2023, indicating a modest strengthening in short-term liquidity excluding inventory.",\n      "relevance": 1.0\n    },\n    {\n      "entity_id": "fy2023",\n      "fact": "FY2023 quick assets = Cash $689M + Trade receivables $1,875M = $2,564M; Current liabilities = $4,476M, giving a quick ratio of ~0.573.",\n      "relevance": 0.95\n    },\n    {\n      "entity_id": "fy2023",\n      "fact": "Total current assets fell to $5,308M in FY2023 from $5,853M in FY2022, but the decline in current liabilities (to $4,476M from $5,103M) helped offset the impact on liquidity ratios.",\n      "relevance": 0.6\n    },\n    {\n      "entity_id": "fy2022",\n      "fact": "FY2022 quick assets = Cash $775M + Trade receivables $1,935M = $2,710M; Current liabilities = $5,103M, giving a quick ratio of ~0.531.",\n      "relevance": 0.95\n    },\n    {\n      "entity_id": "fy2022",\n      "fact": "FY2022 balance sheet included $192M of assets held for sale and $65M of liabilities held for sale, which are excluded from the quick ratio calculation as they are not cash, receivables, or typical current liabilities.",\n      "relevance": 0.4\n    },\n    {\n      "entity_id": "quick_ratio",\n      "fact": "The quick ratio (acid-test ratio) measures a company''s ability to meet short-term obligations using its most liquid assets—cash, marketable securities, and receivables—excluding inventory, making it a standard and relevant liquidity metric for a manufacturing/packaging company like Amcor.",\n      "relevance": 0.9\n    },\n    {\n      "entity_id": "quick_ratio",\n      "fact": "For Amcor, a packaging manufacturer, the quick ratio is particularly relevant because inventory (raw materials and finished goods totaling over $2.2B) constitutes a substantial portion of current assets and may not be quickly convertible to cash, making the quick ratio a more conservative liquidity gauge than the current ratio.",\n      "relevance": 0.7\n    }\n  ],\n  "fact_count": 7,\n  "coverage_notes": "Facts cover the quick ratio calculation inputs and results for both fiscal years, balance sheet context, and rationale for why the quick ratio is a valid, relevant metric for Amcor as a manufacturer with significant inventory."\n}','\n',char(10)),1765,1156,1,NULL,NULL,NULL,'claude-sonnet-5');
INSERT INTO node_attempts VALUES(3357,'3bab7f3c-ce53-4be1-9c54-6af46875ffb5','answer',0,'{"answer":"Amcor''s quick ratio improved slightly from FY2022 to FY2023, rising from about 0.53x to about 0.57x. This was driven by current liabilities falling faster (from $5,103M to $4,476M) than quick assets (cash + trade receivables), which declined from $2,710M to $2,564M. Though both cash and receivables decreased, the larger drop in trade payables and other current liabilities improved the ratio. The quick ratio is a relevant metric for Amcor since inventory is a large, less liquid portion of current assets for a packaging manufacturer, making this a meaningful, modest liquidity improvement.","supporting_entity_ids":["amcor","fy2023","fy2022","quick_ratio"],"confidence":0.85,"confidence_bucket":"high"}',2178,269,0,'length_bound','["length_bound"]','[{"category": "length_bound", "loc": "answer", "type": "string_too_long", "msg": "String should have at most 400 characters"}]','claude-sonnet-5');
INSERT INTO node_attempts VALUES(3358,'3bab7f3c-ce53-4be1-9c54-6af46875ffb5','answer',1,'{"answer":"Amcor''s quick ratio improved slightly from FY2022 (~0.53x) to FY2023 (~0.57x). Quick assets (cash+receivables) fell from $2,710M to $2,564M, but current liabilities fell faster (from $5,103M to $4,476M), boosting the ratio. This metric is relevant since inventory is a large, less liquid asset for a packaging manufacturer like Amcor.","supporting_entity_ids":["amcor","fy2023","fy2022","quick_ratio"],"confidence":0.85,"confidence_bucket":"high"}',2591,202,1,NULL,NULL,NULL,'claude-sonnet-5');
INSERT INTO node_attempts VALUES(3359,'9129925e-113d-4248-8c73-548a02abdd0c','identify',0,'{"entities":[{"name":"Amcor","entity_type":"organization","canonical_id":"amcor"},{"name":"FY2023","entity_type":"concept","canonical_id":"fy2023"},{"name":"FY2022","entity_type":"concept","canonical_id":"fy2022"},{"name":"FY2021","entity_type":"concept","canonical_id":"fy2021"}],"question_type":"what","primary_entity_id":"amcor","entity_count":4}',1493,221,1,NULL,NULL,NULL,'claude-sonnet-5');
INSERT INTO node_attempts VALUES(3360,'9129925e-113d-4248-8c73-548a02abdd0c','gather',0,'{"facts": [{"entity_id": "amcor", "fact": "On August 1, 2022 (FY2022), Amcor acquired 100% equity interest in a Czech Republic flexible packaging manufacturing plant for $59 million, part of the Flexibles segment, recognizing $36 million net assets and $23 million goodwill.", "relevance": 0.95}, {"entity_id": "amcor", "fact": "On March 17, 2023 (FY2023), Amcor acquired 100% equity interest in a medical device packaging manufacturing site in Shanghai, China for $60 million, including $20 million contingent consideration, part of Flexibles segment with $21 million net assets and $39 million goodwill.", "relevance": 0.95}, {"entity_id": "amcor", "fact": "On May 31, 2023 (FY2023), Amcor acquired a New Zealand-based manufacturer of automated protein packaging machines for $45 million, including $13 million contingent consideration.", "relevance": 0.9}, {"entity_id": "fy2022", "fact": "In FY2022, Amcor''s major acquisition was the Czech Republic flexible packaging manufacturing plant completed August 1, 2022, for $59 million within the Flexibles segment.", "relevance": 0.85}, {"entity_id": "fy2023", "fact": "In FY2023, Amcor completed two major acquisitions: a Shanghai, China medical device packaging site (March 17, 2023, $60 million) and a New Zealand protein packaging machinery manufacturer (May 31, 2023, $45 million).", "relevance": 0.9}, {"entity_id": "fy2021", "fact": "The provided filing excerpt does not mention any specific major acquisitions completed by Amcor during FY2021.", "relevance": 0.3}], "fact_count": 6, "coverage_notes": "Filing excerpt details FY2022 and FY2023 acquisitions (Czech Republic, Shanghai, New Zealand) but contains no information on FY2021 acquisitions, which was truncated or not provided."}',1459,702,1,NULL,NULL,NULL,'claude-sonnet-5');
INSERT INTO node_attempts VALUES(3361,'9129925e-113d-4248-8c73-548a02abdd0c','answer',0,replace('{\n  "answer": "In FY2023, Amcor completed two acquisitions within its Flexibles segment: a medical device packaging manufacturing site in Shanghai, China (March 17, 2023) for $60 million, including $20 million contingent consideration, generating $21 million net assets and $39 million goodwill; and a New Zealand-based manufacturer of automated protein packaging machines (May 31, 2023) for $45 million, including $13 million contingent consideration. In FY2022, Amcor''s major acquisition was a Czech Republic flexible packaging manufacturing plant (August 1, 2022) for $59 million, also in the Flexibles segment, resulting in $36 million net assets and $23 million goodwill. No major acquisitions were disclosed for FY2021 in the available filing excerpt.",\n  "supporting_entity_ids": ["amcor", "fy2022", "fy2023", "fy2021"],\n  "confidence": 0.85,\n  "confidence_bucket": "high"\n}','\n',char(10)),1731,335,0,'length_bound','["length_bound"]','[{"category": "length_bound", "loc": "answer", "type": "string_too_long", "msg": "String should have at most 400 characters"}]','claude-sonnet-5');
INSERT INTO node_attempts VALUES(3362,'9129925e-113d-4248-8c73-548a02abdd0c','answer',1,replace('{\n  "answer": "FY2023: Amcor acquired a Shanghai, China medical device packaging site ($60M, incl. $20M contingent) and a New Zealand protein packaging machinery maker ($45M, incl. $13M contingent), both Flexibles segment. FY2022: Acquired a Czech Republic flexible packaging plant for $59M (Flexibles segment). FY2021: No major acquisitions disclosed in the filing excerpt.",\n  "supporting_entity_ids": ["amcor", "fy2022", "fy2023", "fy2021"],\n  "confidence": 0.85,\n  "confidence_bucket": "high"\n}','\n',char(10)),2212,222,1,NULL,NULL,NULL,'claude-sonnet-5');
