INSERT INTO node_attempts VALUES(3367,'12d1c95c-75b1-4a29-97c3-8cfe34b10107','identify',0,replace('{\n  "entities": [\n    {\n      "name": "Amcor",\n      "entity_type": "organization",\n      "canonical_id": "amcor"\n    },\n    {\n      "name": "Gross Margin",\n      "entity_type": "concept",\n      "canonical_id": "gross_margin"\n    },\n    {\n      "name": "FY2023",\n      "entity_type": "other",\n      "canonical_id": "fy2023"\n    }\n  ],\n  "question_type": "what",\n  "primary_entity_id": "amcor",\n  "entity_count": 3\n}','\n',char(10)),991,185,1,NULL,NULL,NULL,'claude-sonnet-5');
INSERT INTO node_attempts VALUES(3368,'12d1c95c-75b1-4a29-97c3-8cfe34b10107','gather',0,replace('{\n  "facts": [\n    {\n      "entity_id": "amcor",\n      "fact": "Amcor''s FY2023 net sales were $14,694 million with cost of sales of $11,969 million, resulting in gross profit of $2,725 million, slightly lower than FY2022''s $2,820 million.",\n      "relevance": 0.9\n    },\n    {\n      "entity_id": "amcor",\n      "fact": "Amcor is a global packaging company, an industry typically characterized by high raw material costs (resins, aluminum, paper) that can compress margins amid inflationary pressure.",\n      "relevance": 0.6\n    },\n    {\n      "entity_id": "gross_margin",\n      "fact": "FY2023 gross margin = 2,725/14,694 = 18.5%, down from FY2022''s 19.4% (2,820/14,544) and FY2021''s 21.2% (2,732/12,861), indicating a declining, not improving, gross margin trend.",\n      "relevance": 1.0\n    },\n    {\n      "entity_id": "gross_margin",\n      "fact": "The three-year gross margin trend (21.2% → 19.4% → 18.5%) shows consistent year-over-year erosion, suggesting cost of sales has grown faster than net sales, likely due to input cost inflation and pass-through pricing lag.",\n      "relevance": 0.95\n    },\n    {\n      "entity_id": "fy2023",\n      "fact": "In FY2023, net sales grew only 1.0% year-over-year ($14,694M vs $14,544M) while cost of sales grew 2.1% ($11,969M vs $11,724M), causing gross profit to shrink and margin to contract.",\n      "relevance": 0.85\n    }\n  ],\n  "fact_count": 5,\n  "coverage_notes": "Covered gross margin calculations across three fiscal years to establish trend direction, plus context on Amcor''s cost structure as a packaging company relevant to margin fluctuations."\n}','\n',char(10)),936,730,1,NULL,NULL,NULL,'claude-sonnet-5');
INSERT INTO node_attempts VALUES(3369,'12d1c95c-75b1-4a29-97c3-8cfe34b10107','answer',0,'{"answer":"No. Amcor''s gross margin has been declining, not improving. Gross margin fell from 21.2% in FY2021 to 19.4% in FY2022 and further to 18.5% in FY2023, as cost of sales (up 2.1% YoY) outpaced net sales growth (up 1.0% YoY), reflecting input cost inflation (resins, aluminum, paper) outstripping pricing pass-through in this packaging business. Gross margin remains a meaningful metric here, and the trend shows margin compression rather than improvement.","supporting_entity_ids":["amcor","gross_margin","fy2023"],"confidence":0.9,"confidence_bucket":"high"}',1163,233,0,'length_bound','["length_bound"]','[{"category": "length_bound", "loc": "answer", "type": "string_too_long", "msg": "String should have at most 400 characters"}]','claude-sonnet-5');
INSERT INTO node_attempts VALUES(3370,'12d1c95c-75b1-4a29-97c3-8cfe34b10107','answer',1,'{"answer":"No. Amcor''s gross margin is declining, not improving: 21.2% (FY21) to 19.4% (FY22) to 18.5% (FY23). Cost of sales grew 2.1% YoY while net sales grew only 1.0%, showing input cost inflation outpacing price pass-through. Gross margin is still meaningful for this packaging company, and the trend reflects clear margin compression.","supporting_entity_ids":["amcor","gross_margin","fy2023"],"confidence":0.9,"confidence_bucket":"high"}',1538,188,1,NULL,NULL,NULL,'claude-sonnet-5');
INSERT INTO node_attempts VALUES(3371,'7220955c-df0e-4240-b62b-d8356ccf606a','identify',0,'{"entities":[{"name":"Amcor","entity_type":"organization","canonical_id":"amcor"},{"name":"Restructuring Liability","entity_type":"concept","canonical_id":"restructuring_liability"},{"name":"Employee Costs","entity_type":"concept","canonical_id":"employee_costs"},{"name":"Fixed Asset Related Costs","entity_type":"concept","canonical_id":"fixed_asset_costs"},{"name":"Q2 FY2023","entity_type":"concept","canonical_id":"q2_fy2023"}],"question_type":"what","primary_entity_id":"amcor","entity_count":5}',1027,375,1,NULL,NULL,NULL,'claude-sonnet-5');
INSERT INTO node_attempts VALUES(3372,'7220955c-df0e-4240-b62b-d8356ccf606a','gather',0,replace('{\n  "facts": [\n    {\n      "entity_id": "amcor",\n      "fact": "Amcor''s restructuring liability represents accrued costs related to company-wide restructuring initiatives, primarily involving employee-related costs, fixed asset write-downs, and other associated expenses.",\n      "relevance": 0.9\n    },\n    {\n      "entity_id": "restructuring_liability",\n      "fact": "As of December 31, 2022 (Q2 FY2023 close), Amcor''s total restructuring liability balance was $93 million, down from $118 million at June 30, 2022, reflecting cash payments and reversals of unused amounts during the period.",\n      "relevance": 1.0\n    },\n    {\n      "entity_id": "restructuring_liability",\n      "fact": "The liability decreased due to $25 million in cash paid, $2 million in net charges to earnings, and $2 million reversal of unused amounts during the six months ended December 31, 2022.",\n      "relevance": 0.85\n    },\n    {\n      "entity_id": "employee_costs",\n      "fact": "Employee costs constitute the largest component of the restructuring liability, totaling $81 million at December 31, 2022 (down from $97 million at June 30, 2022), reflecting severance and workforce reduction obligations tied to Amcor''s restructuring programs.",\n      "relevance": 0.9\n    },\n    {\n      "entity_id": "fixed_asset_costs",\n      "fact": "Fixed asset related costs within the restructuring liability were minimal, decreasing from $3 million at June 30, 2022 to $2 million at December 31, 2022, representing costs tied to asset impairments or disposals from restructuring activities.",\n      "relevance": 0.6\n    },\n    {\n      "entity_id": "q2_fy2023",\n      "fact": "Q2 FY2023 close corresponds to December 31, 2022, the reporting date at which Amcor''s restructuring liability totaled $93 million, comprising $81 million employee costs, $2 million fixed asset costs, and $10 million other costs.",\n      "relevance": 0.95\n    }\n  ],\n  "fact_count": 6,\n  "coverage_notes": "Facts cover the composition, purpose, and movement of Amcor''s restructuring liability from June 30, 2022 to December 31, 2022 (Q2 FY2023 close), addressing employee costs, fixed asset costs, and overall liability changes."\n}','\n',char(10)),1046,813,1,NULL,NULL,NULL,'claude-sonnet-5');
INSERT INTO node_attempts VALUES(3373,'7220955c-df0e-4240-b62b-d8356ccf606a','answer',0,replace('{\n  "answer": "As of Q2 FY2023 close (December 31, 2022), Amcor''s restructuring liability totaled $93 million, reflecting accrued costs from company-wide restructuring initiatives. The liability comprises three components: $81 million in employee costs (severance and workforce reduction obligations, the largest portion), $2 million in fixed asset related costs (impairments/disposals), and $10 million in other costs. This is down from $118 million at June 30, 2022, driven by $25 million in cash paid, $2 million in net new charges to earnings, and a $2 million reversal of unused amounts during the six-month period, indicating the company is actively working through its restructuring program obligations, primarily employee-related.",\n  "supporting_entity_ids": ["amcor", "restructuring_liability", "employee_costs", "fixed_asset_costs", "q2_fy2023"],\n  "confidence": 0.95,\n  "confidence_bucket": "high"\n}','\n',char(10)),1300,322,0,'length_bound','["length_bound"]','[{"category": "length_bound", "loc": "answer", "type": "string_too_long", "msg": "String should have at most 400 characters"}]','claude-sonnet-5');
INSERT INTO node_attempts VALUES(3374,'7220955c-df0e-4240-b62b-d8356ccf606a','answer',1,replace('{\n  "answer": "As of Q2 FY2023 close (Dec 31, 2022), Amcor''s restructuring liability totaled $93M for company-wide restructuring initiatives: $81M employee costs (severance), $2M fixed asset costs (impairments/disposals), $10M other costs. Down from $118M at June 30, 2022, due to $25M cash paid, $2M net new charges, and $2M reversal of unused amounts.",\n  "supporting_entity_ids": ["amcor", "restructuring_liability", "employee_costs", "fixed_asset_costs", "q2_fy2023"],\n  "confidence": 0.95,\n  "confidence_bucket": "high"\n}','\n',char(10)),1767,233,1,NULL,NULL,NULL,'claude-sonnet-5');
