INSERT INTO node_attempts VALUES(3376,'e2631c84-79a7-4e05-aab7-49305d48c7a7','gather',0,replace('{\n  "facts": [\n    {\n      "entity_id": "amcor",\n      "fact": "Amcor''s reported EBITDA for the twelve months ended June 30, 2023 (FY2023) was $2,080 million, up from $1,829 million in FY2022.",\n      "relevance": 0.7\n    },\n    {\n      "entity_id": "adjusted_ebitda",\n      "fact": "Amcor''s Adjusted (Non-GAAP) EBITDA for FY2023 (twelve months ended June 30, 2023) was $2,018 million, compared to $2,117 million in FY2022.",\n      "relevance": 1.0\n    },\n    {\n      "entity_id": "adjusted_ebitda",\n      "fact": "The FY2023 Adjusted EBITDA of $2,018 million was derived by adjusting reported EBITDA of $2,080 million for items including hyperinflation impact (+$24M), property and other losses (+$2M), Russia-Ukraine conflict impacts (-$90M), pension settlements (+$5M), other (-$3M), and amortization of acquired intangibles was not added back in the non-GAAP EBITDA figure per this table''s arrangement.",\n      "relevance": 0.6\n    },\n    {\n      "entity_id": "fy_2023",\n      "fact": "FY2023 refers to Amcor''s fiscal year ended June 30, 2023, for which Adjusted EBITDA was reported as $2,018 million.",\n      "relevance": 0.8\n    }\n  ],\n  "fact_count": 4,\n  "coverage_notes": "Facts cover Amcor''s reported and adjusted EBITDA figures for FY2023 as disclosed in the non-GAAP reconciliation table, directly answering the question."\n}','\n',char(10)),1708,703,1,NULL,NULL,NULL,'claude-sonnet-5');
