INSERT INTO node_attempts VALUES(3379,'a5bdde41-06fa-479f-8ea2-5347b9777c6f','gather',0,replace('{\n  "facts": [\n    {\n      "entity_id": "amcor",\n      "fact": "Amcor''s total net sales grew from $14,544 million in FY2022 to $14,694 million in FY2023, a reported increase of about 1%.",\n      "relevance": 0.9\n    },\n    {\n      "entity_id": "amcor",\n      "fact": "After stripping out FX (-3%), raw material pass-through (+5%) and items affecting comparability (-1%), Amcor''s Comparable Constant Currency (i.e., ''real'') sales growth for the twelve months ended June 30, 2023 versus FY2022 was approximately +1%, driven by -3% volume and +3% price/mix.",\n      "relevance": 1.0\n    },\n    {\n      "entity_id": "amcor",\n      "fact": "By segment for the twelve months, the Comparable Constant Currency growth was +1% for Flexibles and -3% for Rigid Packaging, resulting in a modest overall positive real growth for the total business.",\n      "relevance": 0.8\n    },\n    {\n      "entity_id": "fy_2023",\n      "fact": "FY2023 (twelve months ended June 30, 2023) total net sales were $14,694 million, up from $14,544 million in FY2022.",\n      "relevance": 0.7\n    },\n    {\n      "entity_id": "fy_2023",\n      "fact": "In FY2023, the reported growth rate included a -3% FX headwind and a +5% raw material pass-through benefit, which are excluded when calculating the ''real'' comparable constant currency growth.",\n      "relevance": 0.7\n    },\n    {\n      "entity_id": "fy_2022",\n      "fact": "FY2022 (twelve months ended June 30, 2022) served as the base period with total net sales of $14,544 million, used to calculate FY2023 growth comparisons.",\n      "relevance": 0.6\n    }\n  ],\n  "fact_count": 6,\n  "coverage_notes": "Facts cover Amcor''s reported and comparable constant currency sales growth for FY2023 vs FY2022, isolating the ''real'' growth (~+1%) after removing FX, pass-through costs, and one-off items."\n}','\n',char(10)),1278,1963,1,NULL,NULL,NULL,'claude-sonnet-5');
INSERT INTO node_attempts VALUES(3380,'a5bdde41-06fa-479f-8ea2-5347b9777c6f','answer',0,'{"answer":"Excluding FX movements, raw material pass-through costs, and one-off items affecting comparability, Amcor''s real (comparable constant currency) sales growth for FY2023 vs FY2022 was approximately +1%, driven by -3% volume and +3% price/mix, on total reported net sales of $14,694 million vs $14,544 million.","supporting_entity_ids":["amcor","fy_2023","fy_2022"],"confidence":0.85,"confidence_bucket":"high"}',1536,170,1,NULL,NULL,NULL,'claude-sonnet-5');
