INSERT INTO node_attempts VALUES(3404,'e804a7b1-bd5d-4f12-aca6-bb9518e91ecb','gather',0,'{"facts":[{"entity_id":"debt_securities","fact":"3M has three registered debt securities: 1.500% Notes due 2026 (MMM26), 1.750% Notes due 2030 (MMM30), and 1.500% Notes due 2031 (MMM31).","relevance":1.0},{"entity_id":"new_york_stock_exchange","fact":"All three of 3M''s registered debt securities (MMM26, MMM30, MMM31) are registered to trade on the New York Stock Exchange.","relevance":1.0},{"entity_id":"three_m","fact":"3M trades under symbol MMM, with Common Stock registered on the New York Stock Exchange and the Chicago Stock Exchange, Inc.","relevance":0.7},{"entity_id":"debt_securities","fact":"The 1.500% Notes due 2026 trade under symbol MMM26 on the New York Stock Exchange.","relevance":0.9},{"entity_id":"debt_securities","fact":"The 1.750% Notes due 2030 trade under symbol MMM30 and 1.500% Notes due 2031 trade under symbol MMM31, both on the NYSE.","relevance":0.9},{"entity_id":"q2_2023","fact":"As of Q2 2023, the filing lists the registered debt securities of 3M on a national securities exchange.","relevance":0.6}],"fact_count":6,"coverage_notes":"Facts cover the three registered notes, the exchange they trade on, symbols, and 3M''s common stock listings, all as of Q2 2023."}',991,532,1,NULL,NULL,NULL,'claude-opus-4-8');
INSERT INTO node_attempts VALUES(3405,'e804a7b1-bd5d-4f12-aca6-bb9518e91ecb','answer',0,'{"answer": "As of Q2 2023, 3M has three debt securities registered to trade on a national securities exchange (the New York Stock Exchange): the 1.500% Notes due 2026 (symbol MMM26), the 1.750% Notes due 2030 (symbol MMM30), and the 1.500% Notes due 2031 (symbol MMM31).", "supporting_entity_ids": ["debt_securities", "new_york_stock_exchange", "three_m", "q2_2023"], "confidence": 0.97, "confidence_bucket": "high"}',1132,189,1,NULL,NULL,NULL,'claude-opus-4-8');
