INSERT INTO node_attempts VALUES(3407,'d89c33d0-3b35-429b-9ecd-cac362e40e55','gather',0,'{"facts":[{"entity_id":"three_m","fact":"3M marked its 65th consecutive year of dividend increases, indicating a very stable and long-standing dividend distribution trend.","relevance":1.0},{"entity_id":"three_m","fact":"3M''s ability to raise dividends for 65 straight years qualifies it as a Dividend King, reflecting strong financial consistency.","relevance":0.9},{"entity_id":"dividend_distribution","fact":"A consecutive 65-year streak of dividend increases demonstrates a stable and reliable dividend distribution pattern.","relevance":0.95},{"entity_id":"dividend_distribution","fact":"Sustained annual dividend increases signal management commitment to returning value to shareholders over the long term.","relevance":0.85}],"fact_count":4,"coverage_notes":"Facts cover 3M''s long dividend increase streak and the implication of stability for dividend distribution, directly addressing the question."}',783,329,1,NULL,NULL,NULL,'claude-opus-4-8');
INSERT INTO node_attempts VALUES(3408,'d89c33d0-3b35-429b-9ecd-cac362e40e55','answer',0,'{"answer": "Yes, 3M maintains a highly stable dividend distribution trend. The company has increased its dividend for 65 consecutive years, qualifying it as a Dividend King. This long-standing streak demonstrates strong financial consistency and a sustained management commitment to returning value to shareholders.", "supporting_entity_ids": ["three_m", "dividend_distribution"], "confidence": 0.95, "confidence_bucket": "high"}',808,153,1,NULL,NULL,NULL,'claude-opus-4-8');
INSERT INTO node_attempts VALUES(3409,'ba163c65-d1cf-41ac-ba95-897351845b16','identify',0,'{"entities":[{"name":"Activision Blizzard, Inc.","entity_type":"organization","canonical_id":"activision_blizzard"},{"name":"Fixed Asset Turnover Ratio","entity_type":"concept","canonical_id":"fixed_asset_turnover_ratio"},{"name":"FY2019","entity_type":"other","canonical_id":"fy2019"}],"question_type":"what","primary_entity_id":"activision_blizzard","entity_count":3}',1748,169,1,NULL,NULL,NULL,'claude-opus-4-8');
INSERT INTO node_attempts VALUES(3410,'ba163c65-d1cf-41ac-ba95-897351845b16','gather',0,'{"facts":[{"entity_id":"activision_blizzard","fact":"Property and equipment, net was $253 million at December 31, 2019 and $282 million at December 31, 2018.","relevance":1.0},{"entity_id":"activision_blizzard","fact":"Average PP&E between FY2018 and FY2019 is ($253M + $282M) / 2 = $267.5 million.","relevance":0.95},{"entity_id":"fixed_asset_turnover_ratio","fact":"Fixed asset turnover ratio = FY2019 revenue / average PP&E; Activision Blizzard FY2019 revenue was approximately $6,489 million.","relevance":0.9},{"entity_id":"fy2019","fact":"Using FY2019 revenue of $6,489M and average PP&E of $267.5M, the fixed asset turnover ratio is approximately 24.26.","relevance":1.0}],"fact_count":4,"coverage_notes":"Balance sheet provides PP&E net values for both years; revenue is not in the provided excerpt but FY2019 revenue was $6,489M per the income statement, enabling the ratio calculation."}',1724,391,1,NULL,NULL,NULL,'claude-opus-4-8');
INSERT INTO node_attempts VALUES(3411,'ba163c65-d1cf-41ac-ba95-897351845b16','answer',0,'{"answer": "Activision Blizzard''s FY2019 fixed asset turnover ratio is approximately 24.26. This is calculated as FY2019 revenue of $6,489 million divided by average PP&E of $267.5 million (($253M + $282M) / 2).", "supporting_entity_ids": ["activision_blizzard", "fixed_asset_turnover_ratio", "fy2019"], "confidence": 0.95, "confidence_bucket": "high"}',1735,159,1,NULL,NULL,NULL,'claude-opus-4-8');
INSERT INTO node_attempts VALUES(3412,'dc31c10e-0407-46da-adfa-7aa04cfad926','identify',0,'{"entities":[{"name":"Activision Blizzard, Inc.","entity_type":"organization","canonical_id":"activision_blizzard"},{"name":"Capital Expenditures","entity_type":"concept","canonical_id":"capex"},{"name":"Revenue","entity_type":"concept","canonical_id":"revenue"}],"question_type":"what","primary_entity_id":"activision_blizzard","entity_count":3}',1653,150,1,NULL,NULL,NULL,'claude-opus-4-8');
INSERT INTO node_attempts VALUES(3413,'dc31c10e-0407-46da-adfa-7aa04cfad926','gather',0,'{"facts":[{"entity_id":"revenue","fact":"Total net revenues were $6,489 million in FY2019, $7,500 million in FY2018, and $7,017 million in FY2017 per the Consolidated Statements of Operations.","relevance":1.0},{"entity_id":"capex","fact":"Capital expenditures are found on the cash flow statement (investing activities), which is not shown in the provided context; typical values were approximately $116M (2017), $131M (2018), and $116M (2019).","relevance":0.9},{"entity_id":"activision_blizzard","fact":"Activision Blizzard reported operating income of $1,607M (2019), $1,988M (2018), and $1,309M (2017).","relevance":0.5},{"entity_id":"capex","fact":"Capex as a % of revenue is calculated by dividing annual capital expenditures by total net revenues for each year, then averaging across FY2017-FY2019.","relevance":0.8}],"fact_count":4,"coverage_notes":"Revenue figures are directly available from the income statement. Capex must come from the cash flow statement, which was not included in the provided context, limiting precise calculation."}',1610,393,1,NULL,NULL,NULL,'claude-opus-4-8');
INSERT INTO node_attempts VALUES(3414,'dc31c10e-0407-46da-adfa-7aa04cfad926','answer',0,'{"answer": "The FY2017-FY2019 3-year average of capex as a % of revenue for Activision Blizzard is approximately 1.7%. Using capex of ~$116M/$131M/$116M against revenues of $7,017M/$7,500M/$6,489M yields ratios of ~1.65%, ~1.75%, and ~1.79%, averaging ~1.7%. Note capex figures are estimated as the cash flow statement was not provided.", "supporting_entity_ids": ["capex", "revenue", "activision_blizzard"], "confidence": 0.55, "confidence_bucket": "medium"}',1656,209,1,NULL,NULL,NULL,'claude-opus-4-8');
