INSERT INTO node_attempts VALUES(3419,'0e234e19-783a-482f-a0aa-5e167e5c9741','gather',0,'{"facts":[{"entity_id":"operating_income","fact":"Adobe''s operating income for FY2016 (year ended December 2, 2016) was $1,493,602 thousand.","relevance":1.0},{"entity_id":"operating_income","fact":"Adobe''s operating income for FY2015 (year ended November 27, 2015) was $903,095 thousand.","relevance":1.0},{"entity_id":"fy2016","fact":"FY2016 corresponds to the fiscal year ended December 2, 2016 with total revenue of $5,854,430 thousand.","relevance":0.7},{"entity_id":"fy2015","fact":"FY2015 corresponds to the fiscal year ended November 27, 2015 with total revenue of $4,795,511 thousand.","relevance":0.7},{"entity_id":"adobe","fact":"Adobe Systems Incorporated reports operating income on its Consolidated Statements of Income in thousands of dollars.","relevance":0.6},{"entity_id":"operating_income","fact":"The year-over-year change from FY2015 to FY2016 is (1,493,602 - 903,095) / 903,095 = 65.4%.","relevance":0.9}],"fact_count":6,"coverage_notes":"Facts capture both fiscal years'' operating income figures and the resulting YoY percent change needed to answer the question."}',1632,463,1,NULL,NULL,NULL,'claude-opus-4-8');
INSERT INTO node_attempts VALUES(3420,'0e234e19-783a-482f-a0aa-5e167e5c9741','answer',0,'{"answer":"Adobe''s operating income increased from $903,095 thousand in FY2015 to $1,493,602 thousand in FY2016. The year-over-year change is (1,493,602 - 903,095) / 903,095 = 65.4%.","supporting_entity_ids":["operating_income","fy2015","fy2016"],"confidence":0.99,"confidence_bucket":"high"}',1715,134,1,NULL,NULL,NULL,'claude-opus-4-8');
