INSERT INTO node_attempts VALUES(3473,'f584687d-8a15-4bc0-b2ac-58bb79ad7eb6','gather',0,'{"facts":[{"entity_id":"restructuring_liability","fact":"The restructuring liability balance was $93 million as of December 31, 2022 (Q2 FY2023 close), down from $118 million at June 30, 2022.","relevance":1.0},{"entity_id":"restructuring_liability","fact":"The liability is composed of $81 million in Employee Costs, $2 million in Fixed Asset Related Costs, and $10 million in Other Costs.","relevance":0.95},{"entity_id":"restructuring_liability","fact":"During the period, the liability was affected by $2 million net charges to earnings, $25 million cash paid, and $2 million reversal of unused amounts.","relevance":0.85},{"entity_id":"restructuring_liability","fact":"The largest component is Employee Costs ($81M), indicating the restructuring primarily relates to workforce reductions/severance obligations.","relevance":0.9},{"entity_id":"q2_fy2023","fact":"Q2 FY2023 close corresponds to December 31, 2022, the reporting date for the restructuring liability balance of $93 million.","relevance":0.8},{"entity_id":"amcor","fact":"Amcor is the organization reporting the restructuring liability, tracking costs across employee, fixed asset, and other categories.","relevance":0.7}],"fact_count":6,"coverage_notes":"Facts cover the composition, purpose (employee-focused restructuring), balance changes, and timing of Amcor''s restructuring liability at Q2 FY2023 close."}',984,525,1,NULL,NULL,NULL,'claude-opus-4-8');
INSERT INTO node_attempts VALUES(3474,'f584687d-8a15-4bc0-b2ac-58bb79ad7eb6','answer',0,'{"answer":"As of December 31, 2022 (Q2 FY2023 close), Amcor''s restructuring liability totaled $93 million, down from $118 million at June 30, 2022. Its purpose is primarily to cover workforce reductions/severance, as Employee Costs ($81M) dominate the balance, alongside Fixed Asset Related Costs ($2M) and Other Costs ($10M). During the half-year, the liability was reduced by $25M cash paid and $2M reversal of unused amounts, partly offset by $2M net charges.","supporting_entity_ids":["restructuring_liability","q2_fy2023","amcor"],"confidence":0.92,"confidence_bucket":"high"}',1128,238,0,'length_bound','["length_bound"]','[{"category": "length_bound", "loc": "answer", "type": "string_too_long", "msg": "String should have at most 400 characters"}]','claude-opus-4-8');
INSERT INTO node_attempts VALUES(3475,'f584687d-8a15-4bc0-b2ac-58bb79ad7eb6','answer',1,'{"answer":"As of December 31, 2022 (Q2 FY2023 close), Amcor''s restructuring liability was $93 million, down from $118 million at June 30, 2022. It primarily covers workforce reductions/severance, as Employee Costs ($81M) dominate, plus Fixed Asset Costs ($2M) and Other Costs ($10M). It was reduced by $25M cash paid and $2M reversals, offset by $2M net charges.","supporting_entity_ids":["restructuring_liability","q2_fy2023","amcor"],"confidence":0.92,"confidence_bucket":"high"}',1510,208,1,NULL,NULL,NULL,'claude-opus-4-8');
