INSERT INTO node_attempts VALUES(3477,'eab1ef5f-a45e-4fb8-8dbd-6195dd96ed6a','gather',0,'{"facts":[{"entity_id":"adjusted_non_gaap_ebitda","fact":"Amcor''s Adjusted (Non-GAAP) EBITDA for the twelve months ended June 30, 2023 (FY 2023) was $2,018 million.","relevance":1.0},{"entity_id":"adjusted_non_gaap_ebitda","fact":"For FY 2022, Amcor''s Adjusted EBITDA was $2,117 million, declining to $2,018 million in FY 2023.","relevance":0.7},{"entity_id":"adjusted_non_gaap_ebitda","fact":"Reported (GAAP) EBITDA for FY 2023 was $2,080 million, which was adjusted with items like hyperinflation impact ($24M), Russia-Ukraine impacts (-$90M), and others to arrive at Adjusted EBITDA of $2,018 million.","relevance":0.8},{"entity_id":"amcor","fact":"Amcor reported net income attributable to Amcor of $1,048 million for the twelve months ended June 30, 2023.","relevance":0.5},{"entity_id":"fy_2023","fact":"Fiscal Year 2023 for Amcor refers to the twelve months ended June 30, 2023.","relevance":0.9}],"fact_count":5,"coverage_notes":"Facts directly identify the FY 2023 Adjusted Non-GAAP EBITDA figure ($2,018M), its reconciliation from GAAP EBITDA, and the fiscal year period definition."}',1727,526,1,NULL,NULL,NULL,'claude-opus-4-8');
INSERT INTO node_attempts VALUES(3478,'eab1ef5f-a45e-4fb8-8dbd-6195dd96ed6a','answer',0,'{"answer": "Amcor''s Adjusted (Non-GAAP) EBITDA for FY 2023 (twelve months ended June 30, 2023) was $2,018 million, down from $2,117 million in FY 2022. This was derived by adjusting the reported GAAP EBITDA of $2,080 million for items such as hyperinflation impact ($24M), Russia-Ukraine conflict impacts (-$90M), and others.", "supporting_entity_ids": ["adjusted_non_gaap_ebitda", "fy_2023", "amcor"], "confidence": 0.98, "confidence_bucket": "high"}',1856,212,1,NULL,NULL,NULL,'claude-opus-4-8');
